            'ref_survivor' => 'Eines der bestehenden Tickets',
            'ref_survivor_help' => 'Der Analyst wählt, welches Ticket bestehen bleibt und seine Referenz behält. Die anderen werden geschlossen, behalten ihre eigenen Referenzen und verweisen darauf. Nichts, was einem Anfragenden bereits mitgeteilt wurde, wird zu einer toten Referenz, und Antworten auf ihre alten E-Mails kommen weiterhin an.',
            'ref_new' => 'Ein brandneues Ticket',
            'ref_new_help' => 'Jedes zusammengeführte Ticket wird geschlossen, und eine neue Referenz wird angelegt, die sie alle enthält. Ein sauberer Neuanfang — aber jede Referenz, die Ihre Anfragenden bereits haben, wird zu einer Weiterleitung, und die Uhr des neuen Tickets beginnt heute.',
            'originals_label' => 'Die ursprünglichen Verläufe sollen',
            'orig_thread' => 'In das zusammengeführte Ticket verschoben werden',
            'orig_thread_help' => 'Jede Nachricht wird Teil des Verlaufs des zusammengeführten Tickets, gekennzeichnet mit dem Ticket, aus dem sie stammt. Inline lesbar, in einer Antwort zitierbar und von der Suche gefunden.',
            'orig_thread_html' => 'Verschoben werden, und zusätzlich als HTML-Dateien angehängt werden',
            'orig_thread_html_help' => 'Wie oben, zuzüglich einer eigenständigen HTML-Kopie jedes ursprünglichen Tickets, angehängt an das zusammengeführte — praktisch, wenn Sie jemandem außerhalb von FreeITSM eine vollständige Aufzeichnung aushändigen müssen.',
            'orig_html' => 'Nur als HTML-Dateien angehängt werden',
            'orig_html_help' => 'Die Nachrichten bleiben auf ihren ursprünglichen Tickets, und das zusammengeführte Ticket erhält nur die angehängten Kopien. Das übersichtlichste zusammengeführte Ticket, aber die Suche findet die zusammengeführten Verläufe nicht mehr, weil die Suche Nachrichten liest, nicht Anhänge.',
            'ai_label' => 'Beim Zusammenführen von Tickets eine KI-Zusammenfassung schreiben',
            'ai_help' => 'Fügt dem zusammengeführten Ticket eine Notiz hinzu, die zusammenfasst, worum jeder Anfragende gebeten hat und was bereits getan wurde, damit, wer es übernimmt, nicht jeden Verlauf lesen muss. Erfordert einen im Reiter „Antwort-Bereinigung“ eingerichteten KI-Anbieter. Das Zusammenführen funktioniert auch ohne einen.',
            'note' => 'Zusammengeführte Tickets werden nie gelöscht. Welche Option Sie auch wählen — eine alte Referenz bleibt immer auffindbar und zeigt, wohin sie gegangen ist &mdash; und ein Kunde, der auf eine E-Mail darüber antwortet, erreicht Sie weiterhin.',
