            'per_template_desc' => 'Jede Checkliste hat ihre eigene Regel, festgelegt von der Person, die sie geschrieben hat: Standard warnt den Analysten und protokolliert die Umgehung, Kritisch verweigert den Abschluss, bis jeder Pflichtschritt abgehakt ist.',
            'block_all_title' => 'Jedes Ticket mit offenen Schritten blockieren',
            'block_all_desc' => 'Setzt die Checklisten selbst außer Kraft: Kein Ticket erreicht einen geschlossenen Status, bis jeder Pflichtschritt abgehakt ist - unabhängig davon, was die Checkliste vorgibt. In die andere Richtung gibt es bewusst keine Einstellung - um eine kritische Checkliste zu lockern, bearbeiten Sie die Checkliste, wo die Personen, die ihr folgen, die Änderung sehen können.',
            'empty_section_title' => 'Ein Ticket ohne angehängte Checkliste schließen',
            'empty_section_desc' => 'Manche Teams möchten, dass jedes Ticket einem Verfahren gefolgt ist. Die meisten nicht - ein Passwort-Reset braucht keine Checkliste, und darauf zu bestehen erschwert genau die Tickets, die es am wenigsten verdienen.',
            'empty_off_title' => 'Zulassen (Voreinstellung)',
            'empty_off_desc' => 'Ein Ticket ohne Checkliste wird wie jedes andere geschlossen.',
            'empty_warn_title' => 'Warnen und protokollieren',
            'empty_warn_desc' => 'Der Analyst wird zur Bestätigung aufgefordert und erhält den Anhängen-Dialog angeboten. Trotzdem zu schließen schreibt eine interne Notiz, dass das Ticket ohne Checkliste geschlossen wurde und von wem.',
            'empty_block_title' => 'Abschluss verweigern',
            'empty_block_desc' => 'Das Ticket kann keinen geschlossenen Status erreichen, bis mindestens eine Checkliste daran angehängt ist.',
            'always_recorded' => 'In jedem Fall schreibt das Schließen mit offenen Schritten eine interne Notiz, die die übersprungenen Schritte, die schließende Person und die verwendete Schnittstelle nennt. Diese Einstellungen entscheiden, ob es erlaubt ist, nie, ob es protokolliert wird.',
