        'intros' => [
            'custom_fields' => 'Legen Sie die zusätzlichen Angaben fest, die eine Ticketart benötigt - etwa ein Startdatum und einen Benutzernamen bei neuen Mitarbeitenden - und wählen Sie, bei welchen Tickettypen jede erscheint. Jedes Feld entscheidet selbst, ob es beim Erfassen eines Tickets, beim Schließen oder bei beidem ausgefüllt werden muss und ob die anfragende Person im Portal danach gefragt wird.',
            'checklists' => 'Eine Checkliste kann Schritte als Pflicht markieren. Das legt fest, was passiert, wenn jemand ein Ticket schließt, bevor diese Schritte abgehakt sind.',
            'mandatory_fields' => 'Wählen Sie, welche Ticketfelder vor dem Schließen eines Tickets ausgefüllt sein müssen, und was passiert, wenn jemand eines mit leeren Feldern schließt. Die Regel gilt überall, wo ein Ticket geschlossen werden kann: der Ticket-Bildschirm, Sammelaktionen, die REST-API und Workflows.',
            'departments' => 'Abteilungen gruppieren und leiten Tickets an den richtigen Bereich Ihrer Organisation — legen Sie die an, mit denen Ihr Service Desk Arbeit einordnet und zuweist.',
            'teams' => 'Teams bestimmen, auf welche Abteilungen Analysten zugreifen können. Weisen Sie Teams Abteilungen zu, dann Analysten Teams, um deren Zugriff zu steuern.',
            'ticket_types' => 'Tickettypen klassifizieren, worum es bei einer Anfrage geht (z. B. Störung, Serviceanfrage) — legen Sie die Typen fest, die Analysten an einem Ticket setzen können.',
            'ticket_origins' => 'Ticketquellen erfassen, wie ein Ticket eingegangen ist (z. B. E-Mail, Telefon, Portal) — legen Sie die Quellen fest, aus denen Analysten wählen können.',
            'mailboxes' => 'Postfächer verbinden FreeITSM mit E-Mail-Konten, sodass eingehende Nachrichten zu Tickets werden und Antworten wieder hinausgehen — fügen Sie die hinzu, die Ihr Service Desk überwacht, und authentifizieren Sie sie.',
            'privacy' => 'Ein Ticket enthält nicht nur Ihr Gespräch mit der Person, die es eröffnet hat. Eine Weiterleitung an einen Lieferanten oder eine Kollegin in Kopie setzt diese Nachricht auf dasselbe Ticket — und deren Antwort landet ebenfalls dort. Dies entscheidet, wie viel davon der Anfragende im Self-Service-Portal sieht.',
            'indexing' => 'Der Text in Anhängen wird gelesen, damit er durchsuchbar ist. Word-, Excel-, PowerPoint- und reine Textdateien werden von FreeITSM selbst gelesen, sobald sie eintreffen. PDFs, ältere Office-Dateien und gescannte Dokumente benötigen einen eigenen Dokumentenlesedienst — richten Sie ihn unter <strong>System &rarr; Integrationen &rarr; Apache Tika</strong> ein — und weil diese viel länger brauchen, werden sie im Hintergrund gelesen. Diese beiden Schalter entscheiden, wann diese Hintergrundarbeit stattfindet.',
            'merge_behaviour' => 'Stellt sich heraus, dass zwei Tickets dieselbe Sache sind, kann ein Analyst sie zusammenführen. Diese Einstellungen legen fest, was das mit den Ticketreferenzen macht, die Ihre Anfragenden bereits haben, und was mit den Verläufen geschieht. Sie gelten für alle — eine Zusammenführung ändert, was der Kunde sieht, daher dürfen zwei Analysten am selben Postfach hierüber nicht uneins sein können.',
            'reply_templates' => 'Vorgefertigte Antworten, die Ihre Analysten in eine Antwort einfügen können, statt sie neu zu tippen. Dies sind die gemeinsamen, die das ganze Team sieht — die eigenen privaten Vorlagen eines Analysten werden aus dem Antwortfenster gespeichert und sind hier nicht aufgeführt.',
            'rota_shifts' => 'Schichten sind die Arbeitsmuster-Vorlagen (z. B. Früh, Spät, Bereitschaft), die Analysten im Dienstplan zugewiesen werden — legen Sie sie hier an, bevor Sie den Dienstplan erstellen.',
            'analysts' => 'Analysten sind die Mitarbeitenden, die sich anmelden und Tickets bearbeiten — fügen Sie sie hinzu, setzen Sie Passwörter zurück und weisen Sie sie Teams zu, um ihren Zugriff zu steuern.',
            'general' => 'Die allgemeinen Einstellungen steuern, wie sich Tickets verhalten - Wiedereröffnen, Zurückstellen und wie lange Nachrichten und Threads angezeigt werden.',
            'statuses' => 'Workflow-Zustände, in denen sich ein Ticket befinden kann. Als <em>Geschlossen</em> gekennzeichnete Status gelten als abschließend — verwendet von Berichten, Wachtturm-Zählern und dem automatischen Setzen des Schließungszeitpunkts bei Zuweisung. Genau ein Status ist der Standard für neue Tickets.',
            'priorities' => 'Prioritätsstufen, die an Tickets angezeigt werden. Genau eine Priorität ist der Standard für neue Tickets.',
            'rota_locations' => 'Wo jeder Analyst an einem gegebenen Tag arbeitet — wird vom Dienstplan verwendet und als farbiges Abzeichen an jedem Eintrag angezeigt. Genau ein Standort ist der Standard für neue Dienstplaneinträge.',
            'email_templates' => 'Automatisierte E-Mail-Antworten, ausgelöst durch Ticket-Ereignisse. Nur die erste aktive Vorlage je Ereignis wird verwendet.',
        ],
        'messaging' => [
            'channels_heading' => 'Messaging-Kanäle',
            'channels_intro' => 'Lassen Sie Kunden über WhatsApp mit einem Analysten chatten — jede Nachricht wird zu einem Ticket, genau wie bei E-Mail. Fügen Sie unten einen Kanal hinzu und fügen Sie dann dessen <strong>Webhook-URL</strong> bei Ihrem Anbieter ein (Twilio oder Meta), damit eingehende Nachrichten diese Installation erreichen.',
            'base_url_label' => '<strong>Öffentliche Basis-URL</strong>',
            'base_url_placeholder' => 'https://ihre-domain.de  (oder Ihre ngrok-Adresse beim Testen)',
            'base_url_help' => 'Die Adresse, unter der Anbieter diese Installation erreichen. Legen Sie sie fest, und die Webhook-URLs unten werden kopierbereit. Leer lassen, um die Adresse zu verwenden, über die Sie gerade surfen. Testen Sie lokal? Führen Sie <code>ngrok http 80</code> aus und fügen Sie die ausgegebene <code>https://…ngrok-free.dev</code>-Adresse ein.',
            'templates_heading' => 'Nachrichtenvorlagen',
            'templates_intro' => 'Vorab genehmigte Vorlagen erlauben einem Analysten, <strong>nach Ablauf des 24-Stunden-Fensters</strong> zu antworten. WhatsApp erlaubt Freitext nur innerhalb von 24 Stunden nach der letzten Nachricht des Kunden; danach kann nur eine von Meta/Twilio genehmigte Vorlage gesendet werden. Erstellen und genehmigen Sie die Vorlage bei Ihrem Anbieter, und fügen Sie dann ihre Definition hier hinzu (mit den Platzhaltern <code>{{1}}</code>, <code>{{2}}</code>), damit Analysten sie auswählen und ausfüllen können.',
        ],
