        'sla' => [
            'heading' => 'Service-Level-Agreements',
            'intro' => 'Geschäftszeiten-bewusste SLAs mit Reaktions- und Lösungszielen je Priorität. Die Uhr hält bei Status an, die im <a href="#" onclick="event.preventDefault();switchTab(\'statuses\');">Reiter Status</a> mit „SLA anhalten“ gekennzeichnet sind. Siehe <a href="https://github.com/edmozley/freeitsm/blob/main/docs/sla.md" target="_blank">Entwurfsnotizen</a>.',
