            'col_actions' => 'Aktionen',
            'notifs_heading' => 'Verletzungsmeldungen',
            'notifs_info' => '<strong style="display:block;margin-bottom:6px;font-size:14px;">Wie Benachrichtigungsregeln funktionieren</strong>Jede Regel hat vier Teile: einen <strong>Geltungsbereich</strong>, einen <strong>Auslöser</strong>, ein <strong>Ziel</strong> und eine Liste von <strong>Empfängern</strong>.<br><br><strong>Geltungsbereich</strong> ist entweder <em>Standard</em> (die Regel gilt für Tickets jeder Abteilung) oder eine <em>bestimmte Abteilung</em> (die Regel gilt nur für Tickets dieser Abteilung).<br>Bei der Auswertung eines Tickets sucht das System zuerst nach einer zu seiner Abteilung passenden Regel &mdash; gibt es eine, gewinnt sie, und der Standard wird ignoriert. Gibt es keine abteilungsspezifische Regel, wird die Standardregel verwendet. So können Sie sinnvolle Standardwerte für alle Abteilungen setzen und dann Ausnahmen für Teams mit abweichenden Eskalationsanforderungen festlegen.<br><br><strong>Auslöser</strong> ist entweder <em>Warnung</em> (das Ticket hat die Warnschwelle überschritten &mdash; mögliche Verletzung droht) oder <em>Verletzung</em> (das Ticket hat sein SLA-Ziel jetzt überschritten &mdash; tatsächliche Verletzung). Jedes ist eine eigene Regel, sodass Sie bei Warnungen und Verletzungen unterschiedliche Personen benachrichtigen können.<br><br><strong>Ziel</strong> bestimmt, welche SLA-Uhr beobachtet wird &mdash; <em>Reaktion</em>, <em>Lösung</em> oder <em>Beide</em>.<br><br><strong>Empfänger</strong> können eine beliebige Kombination sein aus: dem aktuell zugewiesenen Analysten des Tickets, jedem Analysten in den Teams der Ticketabteilung, einem namentlich genannten Analysten und/oder einer Liste frei eingegebener E-Mail-Adressen (nützlich für gemeinsame Postfächer oder E-Mail-Brücken zu Slack/Teams).<br><br><strong style="color:var(--warning-text, #92400e);">Keine Regeln = keine E-Mails.</strong> Selbst wenn ein Ticket eine Verletzung aufweist, löst nichts aus, bis Sie mindestens eine Regel hinzufügen (beginnen Sie mit einem Paar Warnung + Verletzung im Geltungsbereich Standard, um alles abzudecken).',
            'notifs_dedup' => 'Je Ticket wird höchstens eine E-Mail pro Kombination aus Ziel und Auslöser versendet &mdash; der Cron-Dienst merkt sich das bereits Versendete, damit Sie keine Duplikate erhalten.',
            'col_scope' => 'Geltungsbereich',
            'col_trigger' => 'Auslöser',
            'col_target' => 'Ziel',
            'col_recipients' => 'Empfänger',
            'col_active' => 'Aktiv',
            'notifs_cron_note' => 'Der Cron-Dienst, der diese E-Mails auslöst, liegt unter <code>cron/sla_breach_check.php</code>. Siehe <code>docs/sla-cron-setup.md</code> für die Einrichtung mit Windows-Aufgabenplanung und Linux-cron.',
            'cron_heading' => 'Cron-Aktivität',
            'cron_refresh' => 'Aktualisieren',
            'cron_intro' => 'Die letzten <span id="slaCronRunsLimit">20</span> Aufrufe des Verletzungsprüfungs-Cron (CLI und HTTP). Einschließlich abgewiesener Anfragen (Rate-Limit, Authentifizierung fehlgeschlagen), damit dieselbe verlässliche Quelle sowohl die Rate-Limit-Prüfungen als auch Sicherheitsaudits stützt. Wird automatisch nach <strong><span id="slaCronRetentionDays">30</span> Tagen</strong> bereinigt; der Mindestabstand zwischen erfolgreichen Läufen beträgt <strong><span id="slaCronMinInterval">30</span>s</strong> (beides in <code>system_settings</code> konfigurierbar).',
            'col_when' => 'Wann',
            'col_source' => 'Quelle',
            'col_duration' => 'Dauer',
            'col_sent' => 'Gesendet',
            'col_skipped' => 'Übersprungen',
            'col_errors' => 'Fehler',
            'col_outcome' => 'Ergebnis',
        ],
        'dept_confidential' => [
            'label' => 'Tickets hier sind vertraulich',
            'help' => 'Jedes Ticket in dieser Abteilung oder jedes dorthin verschobene wird als Vertraulich markiert und so den Vorgesetzten der anfragenden Person vorenthalten. Das Einschalten markiert auch die bereits vorhandenen Tickets. Das Ausschalten ändert kein Ticket - setzen Sie eines am Ticket selbst wieder auf Normal.',
            'chip' => 'Vertraulich',
            'raised' => 'Jetzt als vertraulich markierte Tickets: {count}.',
        ],
        'mailbox_confidential' => [
            'label' => 'Tickets aus diesem Postfach sind vertraulich',
            'help' => 'Für ein Postfach wie HR. Jedes hier eingehende Ticket wird in dem Moment als Vertraulich markiert, in dem es ankommt, bevor es jemand gelesen hat, und so den Vorgesetzten der anfragenden Person vorenthalten.',
        ],
        'pauses_sla' => [
            'label' => 'Hält die SLA-Uhr an',
            'help' => 'Befindet sich ein Ticket in diesem Status, hält die SLA-Uhr an. Verwenden Sie das für Status, in denen nicht aktiv am Ticket gearbeitet wird (z. B. <em>Zurückgestellt</em>, <em>Wartet auf Rückmeldung</em>).',
        ],
        'rota_weekends' => 'Wochenenden im Dienstplan anzeigen',
        'numbering' => [
            'heading' => 'Ticketnummerierung',
            'intro' => 'Jedes Ticket erhält eine Referenz. Sie ist es, was Menschen am Telefon vorlesen, auf ein Formular schreiben und sechs Monate später suchen — es lohnt sich also, dass es etwas ist, das sich aussprechen lässt. Die Form legen Sie hier fest.',
            'style' => 'Wie Nummern gebildet werden',
            'style_sequential' => 'Fortlaufend zählen',
            'style_sequential_help' => 'TICKET-000001, TICKET-000002 und so weiter. Leicht zu sagen, leicht zu erkennen, und die Reihenfolge zeigt, was zuerst kam.',
            'style_random' => 'Zufällig',
            'style_random_help' => 'Drei Buchstaben und acht Ziffern, wie CKQ-418-73926. So hat FreeITSM es schon immer gemacht. Niemand kann erraten, wie viele Tickets Sie haben, aber auch niemand kann eines vorlesen.',
            'format' => 'Wie eine Nummer aussieht',
            'format_help' => 'Setzen Sie <code>{######}</code> dorthin, wo die Ziffern stehen sollen &mdash; eine Raute je Ziffer. Alles andere wird so übernommen, wie Sie es eingeben. Sie können außerdem <code>{YYYY}</code> oder <code>{YY}</code> für das Jahr verwenden, <code>{MM}</code> und <code>{DD}</code>, sowie <code>{TYPE}</code> oder <code>{COMPANY}</code> für ein Kürzel aus dem Tickettyp oder dem Unternehmen. Zum Beispiel <code>INC-{YYYY}-{#####}</code>.',
            'preview_label' => 'Die nächsten sähen so aus',
            'start' => 'Zählung beginnen bei',
            'start_help' => 'Nützlich, wenn Sie von einem anderen System umziehen und dort weitermachen möchten, wo es aufgehört hat.',
            'scope' => 'Getrennt zählen für',
            'scope_global' => 'Eine Reihe für alles',
            'scope_per_type' => 'Jeden Tickettyp',
            'scope_per_company' => 'Jedes Unternehmen',
            'scope_help' => 'Getrennt nach Tickettyp zu zählen gibt Störungen und Anfragen ihre eigenen Nummernreihen — so machen es die meisten großen Service Desks. Zählen Sie getrennt, muss das Format angeben, welche Reihe welche ist — setzen Sie {TYPE} oder {COMPANY} hinein, sonst würde jede Gruppe dieselben Nummern erzeugen.',
            'reset' => 'Neu beginnen',
            'reset_never' => 'Nie — weiterzählen',
            'reset_yearly' => 'Jedes Jahr',
            'reset_monthly' => 'Jeden Monat',
            'reset_help' => 'Nur sinnvoll, wenn Jahr oder Monat Teil der Nummer sind, sonst erhalten Sie Duplikate. Kombinieren Sie es mit etwas wie <code>INC-{YYYY}-{#####}</code>.',
            'existing_note' => '<strong>Bereits vergebene Nummern ändern sich nicht.</strong> Bestehende Tickets behalten ihre Referenz, und jede Referenz, die FreeITSM je vergeben hat, funktioniert weiterhin &mdash; auch in Antworten auf alte E-Mails. Möchten Sie auch bestehende Tickets neu nummerieren, gibt es dafür unten ein Werkzeug. <strong>Ihnen gehen nicht die Ziffern aus:</strong> Die gewählte Breite ist ein Minimum, sodass Ticket 1.000.001 einfach eine Ziffer länger wird, statt zu einem Fehler zu führen.',
            'saved' => 'Ticketnummerierung gespeichert.',
            'renumber_heading' => 'Bestehende Tickets neu nummerieren',
            'renumber_intro' => 'Schreibt die Referenz auf jedem bestehenden Ticket nach dem obigen Schema neu, älteste zuerst. Nützlich vor allem kurz nach dem Umzug von einem anderen System, wenn alles einheitlich aussehen soll.',
            'renumber_safety' => '<strong>Alte Referenzen funktionieren weiter.</strong> Jede Nummer, die ein Ticket je hatte, wird sich gemerkt, sodass eine Antwort auf eine E-Mail mit der alten Nummer weiterhin beim richtigen Ticket landet &mdash; genau wie beim Zusammenführen von Tickets. Eine ausgemusterte Nummer wird auch nie einem anderen Ticket zugewiesen. Das lässt sich aber nicht rückgängig machen, sehen Sie sich also zuerst die Vorschau an.',
            'renumber_preview' => 'Vorschau',
            'renumber_go' => 'Neu nummerieren',
            'renumber_preview_first' => 'Erst die Vorschau — die Schaltfläche wird aktiv, sobald Sie gesehen haben, was passieren würde.',
            'renumber_preview_heading' => 'Nur Vorschau &mdash; es wurde noch nichts geändert.',
            'renumber_done_heading' => 'Tickets neu nummeriert.',
            'renumber_summary' => '{changing} von {total} Ticket(s) würden neu nummeriert. {skipped} passen bereits.',
            'renumber_next_after' => 'Das nächste neue Ticket wäre {number}.',
            'renumber_confirm_title' => 'Jedes Ticket neu nummerieren?',
            'renumber_confirm' => 'Dies schreibt die Referenz auf jedem bestehenden Ticket neu.

Alte Referenzen funktionieren weiter, sodass Antworten auf alte E-Mails weiterhin das richtige Ticket finden. Aber die Nummern, die Menschen aufgeschrieben, auf Formulare übertragen und in ihren eigenen Tabellen gespeichert haben, sind nicht mehr die, die FreeITSM anzeigt.

Das lässt sich nicht rückgängig machen. Fortfahren?',
        ],
        'general' => [
            'system_name' => 'Systemname',
            'system_name_moved' => 'Der Systemname - der erste Teil jedes Seitentitels - wird unter {link} festgelegt, da er für jedes Modul gilt.',
            'system_name_moved_link' => 'System -> Branding',
            'system_name_placeholder' => 'z. B. Service Desk Ticketsystem',
            'system_name_help' => 'Wird am Anfang jedes Seitentitels angezeigt - der Name auf der Browser-Registerkarte und in Lesezeichen. Leer bedeutet „Service Desk“.',
            'reopen_label' => 'Wiedereröffnung',
            'reopen_toggle' => 'Ein geschlossenes Ticket wieder öffnen, wenn der Anfragende antwortet',
            'snooze_hour_label' => 'Beginn des Arbeitstags',
            'snooze_hour_help' => 'Der Zeitpunkt, zu dem ein auf „Morgen“ oder „Nächste Woche“ zurückgestelltes Ticket zurückkommt. Wird in der eigenen Zeitzone jedes Analysten gelesen, sodass ein über mehrere Zeitzonen verteilter Desk jeweils seinen eigenen Morgen bekommt.',
            'collapse_heading' => 'Lange Nachrichten',
            'collapse_desc' => 'Lange E-Mails verdecken das, wofür Sie das Ticket geöffnet haben. Nachrichten, die höher als das Limit sind, werden mit einem Mehr-anzeigen-Link gekürzt. Nichts wird gelöscht — die vollständige Nachricht ist immer einen Klick entfernt.',
            'collapse_enabled_label' => 'Lange Nachrichten kürzen',
            'collapse_lines_label' => 'Nachrichten kürzen, die höher sind als etwa',
            'collapse_lines_help' => 'Zeilen. Eine Nachricht knapp über dem Limit bleibt unangetastet, damit der Link nicht wegen zwei Wörtern erscheint.',
            'collapse_newest_label' => 'Neueste Nachricht immer vollständig anzeigen',
            'collapse_newest_help' => 'Die Nachricht, für die Sie gekommen sind, wird nie gekürzt.',
            'collapse_quoted_label' => 'Zitierten Verlauf kürzen',
            'collapse_quoted_help' => 'Eine kurze Antwort mit einem langen zitierten Verlauf darunter ist nach jeder Zeilenzählung kurz und trotzdem unlesbar, daher wird der zitierte Verlauf separat gekürzt.',
            'collapse_remember_label' => 'Merken, was ich geöffnet habe',
            'collapse_remember_help' => 'Aufgeklappte Nachrichten bleiben auf diesem Gerät aufgeklappt, damit sich das Durcharbeiten eines Verlaufs nicht bei jeder Aktualisierung zurücksetzt.',
            'group_older_label' => 'Ältere Nachrichten einklappen',
            'group_older_help' => 'Über die unten angegebene Anzahl hinaus werden ältere Nachrichten zu einer Zeile zusammengefasst, die Sie öffnen können.',
            'group_show_label' => 'So viele aktuelle Nachrichten offen lassen',
            'flag_duplicates_label' => 'Auf bereits eingegangene Nachrichten hinweisen',
            'flag_duplicates_help' => 'Ein erneuter Versand, eine doppelte Zustellung oder ein Unzustellbarkeitsbericht wird mit einem Hinweis eingeklappt. Nichts wird gelöscht.',
            'team_folders_heading' => 'Team-Ordner',
            'team_folders_label' => 'Analysten sehen',
            'team_folders_all' => 'Alle Teams',
            'team_folders_mine' => 'Nur die Teams, denen sie angehören',
            'team_folders_help' => 'Ändert nur die Ordnerliste - niemand verliert ein Ticket aus den Augen. Ein Team, das Tickets enthält, die ein Analyst sehen kann, wird weiterhin angezeigt, damit die Ordnersummen stimmen. Administratoren sehen immer alle Teams.',
            'ai_heading' => 'AI reading aids',
            'ai_desc' => 'Optional, and off until you turn them on: unlike everything else on this page these use your own AI provider and cost money per use. The provider, model and API key are configured once on the Reply cleanup tab. Nothing an AI writes ever replaces the ticket — the conversation stays exactly where it is, in full.',
            'ai_summary_label' => 'Keep a short AI summary at the top of each ticket',
            'ai_summary_help' => 'A few lines saying where the ticket stands, written on request and kept up to date. It always shows when it was written, how much it read, and how far the conversation has moved on since. Every version is kept, so a worse summary never destroys a better one.',
            'ai_auto_label' => 'Refresh it automatically after this many new messages',
            'ai_auto_help' => '0 means never — the Refresh button is then the only way, and nothing is ever charged without somebody asking. A refresh only happens when an analyst opens the ticket, so a busy queue nobody is reading costs nothing.',
            'ai_max_label' => 'Messages to read',
            'ai_max_help' => 'How far back a summary reads. A longer ticket is read from its most recent end, and the summary says so rather than describing a beginning it never saw.',
            'ai_notes_label' => 'Let it read internal notes',
            'ai_notes_help' => 'Internal notes often hold what was actually tried. They are staff-only either way — the summary is never shown to a requester — but turn this off if notes on your desk hold things that should not leave it.',
            'ai_read_label' => '„Für mich lesen“ bei einem Ticket anbieten',
            'ai_confidential_label' => 'Vertrauliche Tickets und KI',
            'ai_confidential_block' => 'Nie an die KI senden (empfohlen)',
            'ai_confidential_allow' => 'Wie jedes andere Ticket behandeln',
            'ai_confidential_help' => 'Gilt für jede KI-Funktion, die ein Ticket liest: die Zusammenfassung, Für mich lesen,Antwort-Bereinigung, KI fragen, Zusammenfassungen beim Zusammenführen, Wissensartikel-Entwürfe, Kanal-Zusammenfassungen, Problemanalyse und den War-Room-Bot. Ein vertrauliches Ticket wird entweder nicht gesendet oder - wo viele Tickets auf einmal gelesen werden - weggelassen oder nur mit Nummer angezeigt.',
            'ai_read_help' => 'A button that reads the whole ticket and briefs you on it: what happened, what is unresolved, and what it would do next. Asked for and read once, stored nowhere.',
            'reopen_help' => 'Gilt überall, wo ein Anfragender zurückkommt — das Self-Service-Portal, eine Antwort auf Ihre Benachrichtigungs-E-Mail, WhatsApp oder Web-Chat. Das Ticket kehrt in Ihren ersten offenen Status zurück. Nur Tickets in einem als geschlossen gekennzeichneten Status sind betroffen (unter Status einstellbar, welche das sind).',
        ],
        'privacy' => [
            'third_party_label' => 'Nachrichten, die an jemand anderen als den Anfragenden gesendet werden',
            'opt_hide' => 'Vor dem Anfragenden verbergen',
            'opt_hide_help' => 'Die Nachricht und ihre Anhänge erscheinen im Portal des Anfragenden überhaupt nicht. Empfohlen: Die meisten Menschen gehen davon aus, dass die Weiterleitung eines Tickets an einen Lieferanten privat ist.',
            'opt_no_attachments' => 'Die Nachricht anzeigen, aber nicht ihre Anhänge',
            'opt_no_attachments_help' => 'Der Anfragende sieht, dass Sie jemand anderen kontaktiert haben und was geschrieben wurde, kann aber keine angehängten Dateien herunterladen.',
            'opt_show' => 'Alles anzeigen',
            'opt_show_help' => 'Der Anfragende sieht das gesamte Ticket genau wie Ihre Analysten, einschließlich Weiterleitungen und Antworten Dritter. So war es, bevor es diese Einstellung gab.',
            'always_visible_note' => '<strong>Immer sichtbar für den Anfragenden:</strong> seine eigenen Nachrichten und jede an ihn gerichtete Antwort. <strong>Nie sichtbar:</strong> interne Notizen — die sind unabhängig von dieser Einstellung vor dem Portal verborgen. Nachrichten über WhatsApp und Web-Chat werden immer angezeigt, weil diese Gespräche per Definition zwischen dem Anfragenden und Ihrem Desk stattfinden.',
            'timezone' => 'Zeitzone',
            'timezone_help' => 'Wird für die Anzeige von Datum und Uhrzeit im gesamten System verwendet.',
        ],
        'reply_cleanup' => [
            'intro1' => 'Tippt ein Analyst einen groben Entwurf im Ticket-Antwortfenster, formt die Schaltfläche <strong>✨ Bereinigen</strong> ihn zu einer korrekt formatierten E-Mail um — fügt eine Anrede „Sehr geehrte(r) [Name],“ hinzu, korrigiert die Grammatik, wendet den unten gewählten Ton an und schließt mit „Mit freundlichen Grüßen,“. Sie erfindet <strong>keine</strong> technischen Details und füllt den Inhalt nicht künstlich auf.',
            'intro2' => 'Diese Funktion nutzt einen eigenen Anthropic-API-Schlüssel (getrennt von RFP-KI und Wissens-KI), sodass ihre Nutzung als eigene Zeile im Anthropic-Abrechnungsdashboard erscheint.',
            'tone' => 'Ton',
            'tone_friendly' => 'Freundlich (Standard)',
            'tone_formal' => 'Förmlich',
            'tone_brief' => 'Kurz',
            'tone_help' => 'Wird auf jede Bereinigung angewendet, sofern hier nicht geändert.',
            'custom_label' => 'Eigene Anweisungen <span style="color: #999; font-weight: normal;">(optional)</span>',
            'custom_placeholder' => 'z. B. Immer mit „Viele Grüße,“ abschließen&#10;Das Unternehmen als „BillCorp“ bezeichnen&#10;Durchgehend deutsche Rechtschreibung verwenden',
            'custom_help' => 'Wird an den rechts gezeigten System-Prompt angehängt. Nutzen Sie dies für organisationsspezifische Anpassungen (abweichende Grußformeln, Firmenname, Sprachpräferenzen). Die zwingenden Sicherheitsregeln und das Ausgabeformat haben weiterhin Vorrang.',
            'prompt_summary' => 'System-Prompt ansehen (schreibgeschützt)',
            'prompt_panel_intro' => 'Dies ist der vollständige System-Prompt, der bei jeder Bereinigung an Claude gesendet wird. Der Name in der Anrede variiert je Ticket; der Ton spiegelt Ihre Auswahl links wider. Ihre eigenen Anweisungen (falls vorhanden) werden zur Laufzeit am Ende angehängt — sie werden hier nicht angezeigt, bearbeiten Sie sie im Textfeld links.',
        ],
        'csat_tab' => [
            'intro1' => 'Wird ein Ticket geschlossen, erhält der Anfragende eine kurze Umfrage-E-Mail mit der Bitte, die Erfahrung mit 1–5 zu bewerten. Antworten werden dem Analysten zugeordnet, der das Ticket geschlossen hat, sodass Sie CSAT-Trends je Analyst auswerten können, und erscheinen live als Widget auf dem Dashboard.',
            'intro2' => 'Die Umfrage-E-Mail wird unter <a href="#" onclick="event.preventDefault();switchTab(\'email-templates\');">E-Mail-Vorlagen</a> eingerichtet &mdash; erstellen Sie eine Vorlage mit dem Ereignis <strong>CSAT-Umfrage</strong> und betten Sie <code>[csat_link]</code> im Text ein, um die einmalig gültige Bewertungs-URL einzufügen.',
            'mode_off' => 'Aus',
            'mode_off_help' => 'Es werden keine Umfrage-E-Mails versendet.',
            'mode_auto' => 'Automatisch beim Schließen',
            'mode_auto_help' => 'Eine Umfrage wird automatisch versendet, sobald ein Ticket in einen geschlossenen Status wechselt.',
            'mode_manual' => 'Nur manuell',
            'mode_manual_help' => 'Analysten klicken in der Ticket-Werkzeugleiste auf <em>Feedback</em>, wenn sie fragen möchten.',
            'delay_help' => 'Nach dem Schließen so viele Minuten warten, bevor gesendet wird. <code>0</code> = sofort. Nützlich, wenn der Nutzer erst bestätigen soll, dass die Lösung wirklich hält, bevor er um eine Bewertung gebeten wird.',
            'one_per_ticket' => 'Eine Umfrage je Ticket',
            'one_per_ticket_help' => 'Wenn an, erhält ein wiedereröffnetes und dann erneut geschlossenes Ticket nur dann eine weitere Umfrage, wenn ein Analyst sie manuell auslöst &mdash; verhindert, dass ein instabiles Ticket mit Umfragen überhäuft wird.',
            'in_channel' => 'Chat-Kunden in ihrem Chat fragen',
            'in_channel_help' => 'Ein Kunde, der über WhatsApp, Telegram, Slack, Teams oder Mattermost geschrieben hat, wird statt per E-Mail in diesem Chat gefragt &mdash; mit Schaltflächen, wo die App sie hat, und mit &ldquo;Antworten Sie mit 1 bis 5&rdquo;, wo nicht. WhatsApp nur, solange das 24-Stunden-Fenster offen ist; andernfalls und wenn eine Chat-Nachricht fehlschlägt, wird die E-Mail-Umfrage verwendet.',
            'scale_stars' => 'Sterne',
            'scale_emojis' => 'Emojis',
            'scale_help' => 'Beide Optionen speichern dieselbe Zahl von 1–5, sodass Dashboards und Durchschnittswerte in jedem Fall gleich funktionieren &mdash; dies ändert nur, wie die Umfrageseite selbst aussieht.',
        ],
        'analyst_extra' => [
