    'help' => [
        'case' => [
            'nav' => 'Fallberichte',
            'heading' => 'Fallberichte',
            'intro' => 'Wenn ein Prüfer oder Auditor wissen will, wie ein Fall bearbeitet wurde, fasst <strong>Exportieren</strong> das Ticket, seine Konversation und die Aufgaben, die die Arbeit erledigt haben, in einem druckbaren Dokument zusammen - niemand muss es von Hand zusammenkopieren.',
            'step1' => '<strong>Öffnen Sie das Ticket</strong> und wählen Sie in der Symbolleiste <strong>Exportieren</strong> (unter <strong>Mehr</strong>, wenn der Lesebereich schmal ist). Der Bericht öffnet sich in einem neuen Tab. Für eine Aufgabe ohne Ticket verwenden Sie stattdessen die Dokument-Schaltfläche oben im Aufgabenfenster.',
            'step2' => '<strong>Haken Sie an, was enthalten sein soll</strong>, im Bereich links. Der Bericht wird beim Anhaken neu aufgebaut, und während der Auswahl wird nichts protokolliert.',
            'step3' => '<strong>Wählen Sie das Layout</strong>: ein Deckblatt, ein Inhaltsverzeichnis, jeder Abschnitt auf einer neuen Seite sowie eine Kopfzeile mit Seitenzahlen.',
            'step4' => '<strong>Drucken</strong> Sie und wählen Sie im Druckdialog <em>Als PDF speichern</em>. Entfernen Sie das Häkchen bei <em>Kopf- und Fußzeilen</em> des Browsers - der Bericht druckt seine eigenen.',
            'contents' => '<strong>Was enthalten ist:</strong> eine Übersicht des Tickets (mit benutzerdefinierten Feldern, verknüpften Assets, Konfigurationselementen und zugehörigen Tickets); jede Nachricht, die älteste zuerst; die Notizen; die Checklisten des Tickets; jede verknüpfte Aufgabe mit ihren Teilaufgaben, Checklistenergebnissen und Ausnahmenotizen, Formularantworten, befolgten Verfahren, Folgemaßnahmen und Kommentaren; der Verlauf des Tickets und jeder Aufgabe; sowie ein Verzeichnis der Dokumente und E-Mail-Anhänge mit dem Fingerabdruck, den FreeITSM für jedes Dokument erfasst hat.',
            'layout' => '<strong>Layout:</strong> Das Inhaltsverzeichnis listet jeden Abschnitt und jede Aufgabe auf, und jeder Eintrag ist im gespeicherten PDF ein Link. Kopfzeile und Seitenzahlen (<em>Seite 3 von 12</em>) erfordern ein aktuelles Chrome oder Edge; andere Browser drucken den Bericht ohne sie.',
            'who' => '<strong>Wer was sieht:</strong> Der Bericht zeigt nur, was Sie auf dem Bildschirm sehen konnten. Aufgaben, Assets, Konfigurationselemente, zugehörige Tickets, Dokumente und Formularantworten werden jeweils nach ihrer eigenen Regel geprüft, und alles, was Sie nicht sehen dürfen, wird <em>gezählt</em> - nie benannt -, damit der Leser weiß, dass etwas fehlt. <strong>Interne Notizen bleiben außen vor, sofern Sie sie nicht anhaken</strong>, weil ein Bericht meist das Team verlässt.',
            'recorded' => '<strong>Was protokolliert wird:</strong> Das Drucken schreibt eine Zeile <em>Fallbericht</em> in den Audit-Trail des Tickets, mit der Angabe, wer gedruckt hat und welche Abschnitte enthalten waren. Die Vorschau und das Ändern der Auswahl werden nicht protokolliert.',
            'note' => 'Ein Fallbericht ist eine Kopie des Datensatzes, keine Ausarbeitung: Nichts wird umformuliert oder zusammengefasst, Bilder in E-Mails werden nicht wiedergegeben, Dateien werden aufgelistet statt eingebunden, und es erscheint nur Verlauf, den FreeITSM tatsächlich erfasst hat. Ein Abschnitt, der nicht gelesen werden kann, sagt dies in Rot, statt leer auszusehen.',
        ],
        'workspace' => [
            'nav' => 'Arbeitsbereich und Tickettabelle',
            'heading' => 'Der Arbeitsbereich und die Tickettabelle',
            'intro' => 'Zwei weitere Arten, Tickets abzuarbeiten, beide optional. Der <strong>Arbeitsbereich</strong> ordnet ein Ticket zum Arbeiten statt zum Lesen an. Die <strong>Tickettabelle</strong> zeigt die Ticketliste als Tabelle, die Sie filtern, sortieren und speichern können.',
            'ws_title' => 'Der Arbeitsbereich',
            'ws_what' => 'Im Arbeitsbereich stehen die Eigenschaften des Tickets in einer Spalte links, und seine <strong>Konversation</strong>, <strong>Arbeit</strong> (Checklisten und verknüpfte Aufgaben), <strong>Verknüpfungen</strong>, <strong>Zeit und SLA</strong> und <strong>Verlauf</strong> sind Tabs daneben. Die Symbolleiste und alle Bedienelemente sind dieselben wie im Lesebereich - nur der Ort ändert sich. Die eigene <strong>Checkliste</strong> eines Tickets führt auf dem Tab Arbeit jeden Schritt mit seinem Kontrollkästchen auf; <strong>Einklappen</strong> zeigt nur den nächsten Schritt (Ihr Browser merkt sich das), und <strong>Ausklinken</strong> öffnet sie weiterhin in einem eigenen Fenster.',
            'ws_admin' => '<strong>Ein Administrator schaltet ihn ein</strong> unter <strong>Tickets &rarr; Einstellungen &rarr; Allgemein &rarr; Ticket-Arbeitsbereich</strong>: <em>Aus</em> (Standard), <em>Nur Tickets, die in einen Arbeitsbereich umgewandelt wurden</em> oder <em>Jedes Ticket</em>.',
            'ws_make' => '<strong>Ein Ticket in einen Arbeitsbereich umwandeln:</strong> Öffnen Sie bei der mittleren Einstellung das Ticket und wählen Sie <strong>Mehr &rarr; Arbeitsbereich erstellen</strong> (und <strong>Zurück zum Lesebereich</strong>, um es rückgängig zu machen). Es gehört zum Ticket, daher sehen alle, die es bearbeiten, es gleich, und es wird im Verlauf des Tickets protokolliert.',
            'ws_own' => '<strong>Ihre eigene Wahl:</strong> Sobald er eingeschaltet ist, schaltet <strong>Arbeitsbereich verwenden</strong> im Filtermenü der Liste oder unter <strong>System &rarr; Einstellungen</strong> ihn nur für Sie aus. Ein in einen Arbeitsbereich umgewandeltes Ticket zeigt dann ein kleines Kennzeichen <em>Arbeitsbereich</em>, damit Sie wissen, dass ein Kollege es auf diese Weise bearbeitet.',
            'ws_checklist' => '<strong>Die Checklisten des Tickets führen jeden Schritt auf:</strong> Auf dem Tab <strong>Arbeit</strong> zeigt eine Checkliste alle ihre Schritte mit Kontrollkästchen. <strong>Einklappen</strong> verkleinert sie auf den nächsten Schritt, wie ihn der Lesebereich zeigt, und <strong>Aufklappen</strong> bringt den Rest zurück - Ihr Browser merkt sich Ihre Wahl. <strong>Ausklinken</strong> öffnet die vollständige Checkliste weiterhin in einem Fenster.',
            'ws_tasks' => '<strong>Verknüpfte Aufgaben öffnen sich an Ort und Stelle:</strong> Klicken Sie auf dem Tab <strong>Arbeit</strong> auf eine Aufgabe, und ihr eigener Editor öffnet sich dort - mit Checklisten, Formularen, Verfahren, Teilaufgaben, Kommentaren und Dokumenten. <strong>Separat öffnen</strong> öffnet sie wie bisher in einem eigenen Fenster; Strg-Klick tut dasselbe. Zum Bearbeiten benötigen Sie Zugriff auf Aufgaben.',
            'ws_safe' => '<strong>Nichts Halbgetipptes geht verloren:</strong> Wenn Sie mit einer ungespeicherten Antwort, Notiz oder Aufgabenänderung zu einem anderen Ticket wechseln oder den Arbeitsbereich ausschalten, werden Sie zuerst gefragt, und es wird auf alles gewartet, was noch gespeichert wird.',
            'tb_title' => 'Die Tickettabelle',
            'tb_what' => 'Wählen Sie in der Aktionsleiste oben in Tickets <strong>Tabelle</strong> statt <strong>Nachrichten</strong> (oder unter <strong>System &rarr; Einstellungen</strong>). Der Ordner, in dem Sie sich befinden, wird zum Filter der Tabelle; wählen Sie Spalten, filtern und sortieren Sie sie, suchen Sie und blättern Sie in 25, 50 oder 100 Tickets pro Seite durch die Liste. <strong>Ansicht speichern</strong> sichert ein Layout für Sie selbst, Ihr Team oder alle.',
            'tb_same' => 'Klicken, Strg- und Umschalt-Klick, Rechtsklick, Ziehen in einen Ordner und die Massenaktionen funktionieren alle wie in der Nachrichtenliste, und die Tabelle zeigt nie ein Ticket, das die Liste nicht zeigen würde.',
            'tb_export' => '<strong>CSV-Export:</strong> Die CSV-Schaltfläche exportiert <em>jedes</em> passende Ticket, nicht nur die Seite, mit den Spalten, die Sie gerade anzeigen. Wer sie verwenden darf, wird unter <strong>Tickets &rarr; Einstellungen &rarr; Allgemein &rarr; Wer die Ticketliste exportieren darf</strong> festgelegt: nur Administratoren (Standard), alle mit Zugriff auf Tickets oder niemand. Die Schaltfläche wird niemandem angezeigt, dem sie nicht offensteht.',
        ],
        'page_title' => 'Service Desk - Ticket-Anleitung',
        'sidebar_title' => 'Anleitung',
        'hero_title' => 'Anleitung zum Ticket-Modul',
        'hero_sub' => 'Erfassen, verfolgen und lösen Sie IT-Supportanfragen aus einem einzigen, ordnerbasierten Posteingang &mdash; entwickelt für Service-Desk-Teams.',
        'nav' => [
            'overview' => 'Überblick',
            'inbox' => 'Der Posteingang',
            'working_with_tickets' => 'Mit Tickets arbeiten',
            'working_faster' => 'Schneller arbeiten',
            'comments_attachments' => 'Kommentare &amp; Anhänge',
            'ai_tools' => 'KI-Werkzeuge',
            'csat' => 'CSAT-Umfragen',
            'user_management' => 'Benutzerverwaltung',
            'dashboard' => 'Dashboard',
            'calendar_rota' => 'Kalender &amp; Dienstplan',
            'settings' => 'Einstellungen',
            'tips' => 'Kurztipps',
            'companies' => 'Unternehmen',
        ],
        'overview' => [
            'heading' => 'Überblick',
            'intro' => 'Das Ticket-Modul ist das Kernstück Ihres IT-Service-Desks. Es bietet eine vertraute, E-Mail-Client-artige Oberfläche zur Verwaltung von Supportanfragen, Störungen und Servicevorgängen. Tickets gehen von Endbenutzern per E-Mail oder manueller Erstellung ein, und Analysten arbeiten sie mithilfe von Ordnern, Prioritäten und SLA-Timern ab &mdash; alles, was Sie für einen reaktionsschnellen IT-Support benötigen.',
            'card_inbox_title' => 'Posteingang',
            'card_inbox_body' => 'Ein ordnerbasierter Posteingang nach dem Vorbild eines E-Mail-Clients. Durchsuchen Sie die Ordner Meine Tickets, Nicht zugewiesen, Alle offenen und Geschlossen. Klicken Sie auf ein Ticket, um ein Lesefenster mit allen Details, dem Verlauf und den verfügbaren Aktionen zu öffnen.',
            'card_dashboard_title' => 'Dashboard',
            'card_dashboard_body' => 'Erstellen Sie ein persönliches Dashboard mit anpassbaren Chart.js-Widgets. Visualisieren Sie Ticketaufkommen, Reaktionszeiten, Kategorieaufschlüsselungen und Analystenauslastung mit Balken-, Kreis-, Ring- und Liniendiagrammen.',
            'card_calendar_title' => 'Kalender',
            'card_calendar_body' => 'Zeigen Sie Tickets in einem Kalenderraster an, basierend auf ihrem Erstellungs-, Fällig- oder Lösungsdatum. Erkennen Sie überfällige Vorgänge schnell und planen Sie Ihre Woche mit einem Blick auf die gesamte Ticketlage.',
            'card_rota_title' => 'Dienstplan',
            'card_rota_body' => 'Planen Sie Analystenschichten und Bereitschaftsdienste. Sehen Sie, wer wann verfügbar ist, planen Sie die Abdeckung für Wochenenden und Feiertage, und stellen Sie sicher, dass kein Ticket unbeachtet bleibt.',
        ],
        'inbox' => [
            'heading' => 'Der Posteingang',
            'intro' => 'Der Posteingang ist der zentrale Arbeitsbereich für Analysten. Er nutzt ein Drei-Spalten-Layout &mdash; Ordner links, eine Ticketliste in der Mitte und ein Lesefenster rechts &mdash; sodass Sie Tickets bewerten und beantworten können, ohne die Seite zu verlassen.',
            'p_live' => '<strong>Er hält sich selbst aktuell.</strong> Jede Minute prüft der Posteingang Ihre Postfächer und sucht nach Neuem bei Tickets, die Sie sehen können &mdash; eine im Hintergrund abgeholte E-Mail, eine Nachricht über WhatsApp, Telegram, Slack, Teams oder Mattermost, die Antwort eines Kollegen &mdash; und wenn etwas eingetroffen ist, werden die Liste und die Ordnerzähler von selbst aktualisiert, genau wie mit der Schaltfläche „Aktualisieren“. Das Ticket, das Sie gerade lesen, und jede Antwort, die Sie gerade tippen, bleiben unberührt.',
            'p_folders' => 'Das Ordnerpanel gliedert Tickets in logische Gruppen. Jeder Ordner zeigt eine Anzahl ungelesener Tickets, damit Sie neue Vorgänge sofort erkennen:',
            'field_my' => '<strong>Meine Tickets</strong> &mdash; Ihnen zugewiesene Tickets. Dies ist Ihre persönliche Warteschlange und der beste Ausgangspunkt für jeden Tag.',
            'field_unassigned' => '<strong>Nicht zugewiesen</strong> &mdash; eingegangene Tickets ohne Analysten. Übernehmen Sie hier Vorgänge, um deren Eigentümer zu werden.',
            'field_all_open' => '<strong>Alle offenen</strong> &mdash; jedes noch nicht geschlossene Ticket, unabhängig vom Eigentümer. Nützlich für Manager und Teamleiter, die das Gesamtaufkommen überwachen.',
            'field_closed' => '<strong>Geschlossen</strong> &mdash; gelöste Tickets. Suchen Sie hier, wenn Sie eine frühere Lösung nachschlagen oder einen Vorgang wieder öffnen müssen.',
            'field_dept' => '<strong>Abteilungsordner</strong> &mdash; Tickets gruppiert nach Abteilung (z. B. IT, HR, Finanzen). Abteilungen werden in den Einstellungen konfiguriert und erscheinen automatisch als Unterordner.',
            'switch_heading' => '<strong>Zwischen Gruppierung nach Abteilung und nach Analyst wechseln</strong>',
            'switch_body' => 'Ein kleiner Zwei-Schalter-Umschalter oben im Ordnerpanel wechselt zwischen zwei Ansichten derselben Daten. Die Gruppierung <strong>Abteilung</strong> (Standard) listet Tickets unter jeder Abteilung mit Status-Unterordnern auf; die Gruppierung <strong>Analyst</strong> dreht dies um, sodass jeder oberste Ordner die persönliche Warteschlange eines Analysten mit Status-Unterordnern darstellt. Der Ordner <strong>Nicht zugewiesen</strong> passt sich der jeweiligen Ansicht an &mdash; in der Abteilungsansicht listet er Tickets ohne Abteilung, in der Analystenansicht Tickets ohne Bearbeiter &mdash; sodass Sie immer sehen, was noch übernommen werden muss. Ihre Wahl wird pro Analyst gespeichert, sodass jedes Teammitglied die bevorzugte Ansicht sitzungsübergreifend behält.',
            'p_actions' => 'Über der Ticketliste finden Sie vier Aktionsschaltflächen: <strong>Neu</strong>, um ein Ticket zu erstellen, <strong>Suchen</strong>, um Tickets nach Stichwort, Referenz oder Anfragendem zu finden, <strong>Filter</strong>, um einzuschränken, was Sie sehen, und <strong>Aktualisieren</strong>, um den aktuellen Ordner neu zu laden.',
            'filter_body' => 'Die Schaltfläche <strong>Filter</strong> (der Trichter) schränkt Ordner und Liste gemeinsam ein, egal wie sie gruppiert sind. <strong>Meine</strong> zeigt nur Tickets, die Ihnen zugewiesen sind, und <strong>Geschlossene ausblenden</strong> lässt jedes Ticket weg, dessen Status als geschlossen markiert ist. Solange ein Filter aktiv ist, trägt der Trichter einen Punkt und neben dem Listentitel erscheint eine Bezeichnung, damit Sie immer wissen, dass Sie nicht alles sehen. Wenn die Ordner nach <strong>Analyst</strong> gruppiert sind, steht stattdessen Ihr eigener Ordner als <strong>Meine Tickets</strong> ganz oben. Die Suche hat einen eigenen Schalter <strong>Geschlossene Tickets einbeziehen</strong>, der standardmäßig an ist, weil eine Suche meist der Suche nach einem alten Ticket dient. Beide Einstellungen werden nur für Sie gespeichert.',
            'row_name' => 'Jede Zeile zeigt die Ticketreferenz und dann einen Namen. Standardmäßig ist das <strong>die Person, die das Ticket gemeldet hat</strong>, und das bleibt für die Lebensdauer des Tickets so. Möchten Sie stattdessen sehen, wer die letzte Nachricht gesendet hat &mdash; was zu Ihrem eigenen Postfach wird, sobald Sie geantwortet haben &mdash;, ändern Sie <strong>Name neben der Ticketnummer</strong> unter <strong>Einstellungen &rarr; Zeilenanzeige</strong>, wo Sie den Namen auch ausblenden und nur die Referenz stehen lassen können. Dieser Tab ist Ihre eigene Einstellung: Sie ändert nichts für andere.',
            'tip' => 'Klicken Sie auf ein Ticket in der Liste, um es im Lesefenster zu laden. Von dort aus können Sie Felder aktualisieren, Kommentare hinzufügen, per E-Mail antworten oder Dateien anhängen &mdash; alles, ohne den Posteingang zu verlassen.',
        ],
        'faster' => [
            'heading' => 'Schneller arbeiten',
            'intro' => 'Vier Dinge, die aus einem hektischen Morgen einen zu bewältigenden machen: gespeicherte Antworten, das gleichzeitige Bearbeiten mehrerer Tickets und das Einordnen von Konversationen dorthin, wo sie hingehören.',
            'templates_heading' => 'Vorgefertigte Antworten',
            'templates_body' => 'Sie senden ständig dieselben paar Antworten. Schreiben Sie eine einmal, und klicken Sie dann unten links im Antwortfenster auf <strong>Vorlagen</strong>, um sie an der Cursorposition einzufügen &mdash; sie wird zu dem hinzugefügt, was Sie bereits getippt haben, und ersetzt es nicht. Vorlagen sind Rich-Text und unterstützen dieselben <code>[merge_code]</code>-Platzhalter wie die automatischen E-Mails, sodass <code>[requester_first_name]</code> beim Einfügen zum echten Namen wird.',
            'templates_team' => '<strong>Team-Vorlagen</strong> &mdash; mit allen geteilt, eingerichtet unter Einstellungen &rarr; Antwortvorlagen.',
            'templates_mine' => '<strong>Ihre eigenen</strong> &mdash; speichern Sie einen Entwurf über <em>Entwurf als Vorlage speichern</em>. Nur für Sie sichtbar, keine Berechtigung erforderlich.',
            'templates_tip' => 'Benennen Sie eine Vorlage nach der Situation ("Drucker offline &mdash; erste Schritte"), nicht nach ihrem Wortlaut. Danach suchen Sie um 9 Uhr morgens.',
            'select_heading' => 'Mehrere Tickets auswählen',
            'select_body' => 'Die Ticketliste funktioniert wie Outlook oder der Datei-Explorer. Keine Kontrollkästchen.',
            'key_click' => 'Klick',
            'key_click_d' => 'eines auswählen und öffnen',
            'key_ctrl' => 'Strg+Klick',
            'key_ctrl_d' => 'eines hinzufügen oder entfernen, der Rest bleibt unverändert',
            'key_shift' => 'Umschalt+Klick',
            'key_shift_d' => 'einen ganzen Block ab der letzten Klickposition auswählen',
            'key_kb' => 'Tastatur',
            'key_kb_d' => 'Pfeiltasten zum Bewegen, Umschalt+Pfeiltasten zum Erweitern, Strg+Pfeiltasten und Leertaste zum Auswählen einzelner Tickets, Strg+A für alle, Esc zum Aufheben',
            'select_actions' => 'Bei mehreren ausgewählten Tickets können Sie mit <strong>Rechtsklick auf eines davon</strong> Status, Priorität, Abteilung, Typ oder Bearbeiter für alle gleichzeitig festlegen &mdash; oder die gesamte Auswahl auf einen Ordner ziehen. Was der Bildschirm bei mehreren ausgewählten Tickets anzeigt, wählen Sie im Kontomenü unter Einstellungen.',
            'select_tip' => 'Ein Rechtsklick auf ein Ticket, das <em>nicht</em> Teil Ihrer Auswahl ist, hebt die Auswahl auf und wirkt nur auf dieses eine Ticket. Das ist beabsichtigt &mdash; so können Sie nie versehentlich auf eine Auswahl einwirken, die Sie bereits vergessen haben.',
            'merge_heading' => 'Duplikate zusammenführen',
            'merge_body' => 'Zwei Personen haben denselben Ausfall gemeldet? Wählen Sie die Tickets aus, Rechtsklick, <strong>Zusammenführen</strong>. Die Konversationen werden vereint, und wenn ein KI-Anbieter konfiguriert ist, schreibt FreeITSM eine kurze Zusammenfassung dessen, was alle gefragt haben und was bereits getan wurde, sodass niemand vier Verläufe lesen muss, der den Vorgang übernimmt.',
            'merge_tip' => 'Es geht nie etwas verloren. Das zusammengeführte Ticket behält seine Referenz, bleibt durchsuchbar, zeigt an, wohin es verschoben wurde &mdash; und ein Kunde, der auf eine alte E-Mail dazu antwortet, erreicht Sie weiterhin.',
            'split_heading' => 'Ein Ticket aufteilen',
            'split_body' => 'Die umgekehrte Aufgabe. Wenn jemand mitten in einer Konversation ein zweites, unabhängiges Anliegen aufwirft, klicken Sie bei dieser Nachricht auf <strong>Aufteilen</strong> (oder machen Sie einen Rechtsklick auf die Nachrichtenkopfzeile). Sie wandert in ein neues Ticket, wahlweise mit allen neueren Nachrichten, und das ursprüngliche Ticket behält einen Hinweis darauf, wohin sie gegangen sind.',
            'split_tip' => 'Geben Sie dem neuen Ticket einen passenden Betreff. Standardmäßig übernimmt er den der verschobenen Nachricht, was meist ein "RE:" zum <em>alten</em> Problem ist.',
            'undo_heading' => 'Es sich anders überlegt',
            'undo_body' => 'Beides lässt sich über das Banner am Ticket rückgängig machen. Das Rückgängigmachen eines <strong>Aufteilens</strong> wird verweigert, sobald jemand im neuen Ticket geantwortet, eine Notiz hinzugefügt oder Zeit erfasst hat &mdash; Ihnen wird genau mitgeteilt, was im Weg steht. Das Rückgängigmachen eines <strong>Zusammenführens</strong> gibt dem Ticket seine Nachrichten, Notizen und erfasste Zeit zurück und öffnet es genau wie zuvor wieder, aber Antworten, die seit dem Zusammenführen am anderen Ticket geschrieben wurden, verbleiben dort.',
        ],
        'working' => [
            'heading' => 'Mit Tickets arbeiten',
            'intro' => 'Jede Supportanfrage durchläuft einen Lebenszyklus: Sie wird erstellt, bewertet, bearbeitet und schließlich gelöst. Das Ticket-Modul liefert Ihnen die Werkzeuge, um jede Phase effizient zu verwalten, von der ersten Erfassung bis zum Abschluss.',
            'creating_heading' => '<strong>Ein neues Ticket erstellen</strong>',
            'step1' => '<strong>Auf Neu klicken</strong> &mdash; öffnet das Dialogfeld für ein neues Ticket über die Symbolleiste des Posteingangs. Geben Sie Namen und E-Mail-Adresse des Anfragenden ein, damit er Updates erhalten kann.',
            'step2' => '<strong>Betreff festlegen</strong> &mdash; schreiben Sie eine klare, prägnante Zusammenfassung des Problems. Dieser erscheint in der Ticketliste und in allen E-Mail-Benachrichtigungen an den Endbenutzer.',
            'step3' => '<strong>Abteilung, Typ und Priorität wählen</strong> &mdash; wählen Sie die passende Abteilung, den Tickettyp (z. B. Störung, Serviceanfrage) und die Prioritätsstufe. Diese Felder steuern SLA-Timer und Routing-Regeln.',
            'step4' => '<strong>Beschreibung hinzufügen</strong> &mdash; geben Sie mit dem Rich-Text-Editor alle Details zum Problem an. Fügen Sie Schritte zur Reproduktion, Fehlermeldungen und jeden relevanten Kontext hinzu, den der bearbeitende Analyst benötigt.',
            'step5' => '<strong>Speichern</strong> &mdash; das Ticket wird mit einer eindeutigen Referenznummer erstellt und erscheint im passenden Ordner. Die SLA-Uhr beginnt sofort, basierend auf der Priorität.',
            'editing_heading' => '<strong>Tickets bearbeiten und verwalten</strong>',
            'editing_body' => 'Sobald ein Ticket besteht, können Sie jedes Feld im Lesefenster aktualisieren. Wichtige Felder sind:',
            'card_status_title' => 'Status',
            'card_status_body' => 'Verfolgen Sie den Ticket-Lebenszyklus: Neu, Offen, In Bearbeitung, Wartend, Gelöst, Geschlossen',
            'card_priority_title' => 'Priorität',
            'card_priority_body' => 'Legen Sie Dringlichkeit und Auswirkung fest: Kritisch, Hoch, Mittel, Niedrig. Jede Stufe hat ihr eigenes SLA-Ziel',
            'card_category_title' => 'Kategorie',
            'card_category_body' => 'Klassifizieren Sie die Art des Problems: Hardware, Software, Netzwerk, Zugriff, Allgemein. Nützlich für Auswertungen',
            'card_analyst_title' => 'Zugewiesener Analyst',
            'card_analyst_body' => 'Die für die Lösung des Tickets verantwortliche Person. Eine Neuzuweisung wird im Aktivitätsprotokoll erfasst',
            'card_enduser_title' => 'Endbenutzer',
            'card_enduser_body' => 'Die Person, die die Anfrage gestellt hat. Suchen Sie nach Name oder E-Mail, um mit einem bestehenden Benutzerdatensatz zu verknüpfen',
            'card_dept_title' => 'Abteilung',
            'card_dept_body' => 'Leiten Sie Tickets an das richtige Team weiter. Abteilungen steuern die Ordnergruppierung und die Dashboard-Filter',
            'flow_new' => 'Neu',
            'flow_in_progress' => 'In Bearbeitung',
            'flow_resolved' => 'Gelöst',
            'flow_closed' => 'Geschlossen',
            'triage_heading' => '<strong>Bewertung per Ziehen und Ablegen</strong>',
            'triage_body' => 'Sie müssen ein Ticket nicht öffnen, um es zu bewerten. Ziehen Sie eine Zeile aus der Ticketliste auf einen Ordner, um Felder in einem Schritt zu aktualisieren:',
            'triage_dept' => '<strong>Abteilungsansicht</strong> &mdash; auf einen Abteilungsordner ablegen, um neu zuzuweisen; auf einen Status-Unterordner unter einer Abteilung ablegen, um beides gleichzeitig zu aktualisieren; auf <strong>Nicht zugewiesen</strong> ablegen, um die Abteilung zu entfernen.',
            'triage_analyst' => '<strong>Analystenansicht</strong> &mdash; auf den Ordner eines Analysten ablegen, um diesen als Eigentümer festzulegen (setzt sowohl <code>assigned_analyst_id</code> als auch <code>owner_id</code>, sodass das Feld Eigentümer im Lesefenster synchron bleibt); auf einen Status-Unterordner ablegen, um beides zu aktualisieren; auf <strong>Nicht zugewiesen</strong> ablegen, um den Bearbeiter zu entfernen.',
            'triage_spring' => '<strong>Selbstöffnende Ordner</strong> &mdash; halten Sie beim Ziehen über einem eingeklappten Ordner an, öffnet er sich automatisch (wie in Outlook), sodass jeder verschachtelte Status erreichbar ist, ohne vorher abzulegen.',
            'fullscreen_heading' => '<strong>Vollbildansicht</strong>',
            'fullscreen_body' => 'Wenn Sie sich auf ein einzelnes Ticket konzentrieren müssen &mdash; eine lange Konversation, eine komplexe Änderung, eine ausführliche Antwort verfassen &mdash; wechseln Sie in die Vollbildansicht. Die Ordnerliste und die Ticketliste verschwinden, die Konversation füllt die verfügbare Breite, und die Eigenschaften (Abteilung, Typ, Status, Quelle, Sofortlösung, IT-Schulung, Eigentümer) wandern in eine vertikale Seitenleiste rechts.',
            'fullscreen_max' => '<strong>Maximieren-Symbol</strong> &mdash; kleines Symbol am rechten Ende der Ticket-Betreffzeile. Klicken, um in die Vollbildansicht zu wechseln; erneut klicken, um zum 3-Spalten-Layout zurückzukehren.',
            'fullscreen_dbl' => '<strong>Doppelklick auf eine Zeile oder Eingabetaste</strong> &mdash; doppelklicken Sie ein Ticket in der Liste oder drücken Sie <strong>Eingabe</strong> auf dem markierten, um es direkt in der Vollbildansicht zu öffnen, eine Outlook-artige Geste für "dieses hier wirklich öffnen". Beides funktioniert in der Nachrichten- und der Tabellenliste.',
            'fullscreen_sticks' => '<strong>Bleibt beim Wechseln erhalten</strong> &mdash; sind Sie einmal in der Vollbildansicht, bleiben Sie beim Wechsel zum nächsten Ticket dort. Ein Neuladen der Seite (F5) ohne ausgewähltes Ticket kehrt zum Standard-3-Spalten-Layout zurück, sodass Sie nie mit ausgeblendeter Ordnerliste feststecken können.',
            'fullscreen_back' => '<strong>Zurück</strong> &mdash; die Leiste über dem Ticket zeigt seine Nummer und eine Schaltfläche <strong>Zurück</strong>, die Sie genau so zur Liste zurückbringt, wie Sie sie verlassen haben, mit der Tastatur wieder auf der Liste - die Pfeiltasten wechseln zwischen den Tickets und die Eingabetaste öffnet sofort das nächste. <strong>Esc</strong> tut dasselbe, sobald jedes Fenster oder Menü über dem Ticket geschlossen ist.',
            'fullscreen_keys' => '<strong>Die Tasten scrollen das Ticket</strong> &mdash; in der Vollbildansicht scrollen die Pfeiltasten, Bild auf / Bild ab und die Leertaste den Verlauf, nicht die ausgeblendete Ticketliste. In einem Bild- oder PDF-Fenster scrollen sie dieses Fenster. In der normalen dreispaltigen Ansicht klicken Sie ins Ticket, und die Tasten scrollen es ebenfalls; ein Klick in die Liste wechselt wieder zwischen den Tickets.',
            'viewer_heading' => '<strong>Bilder und PDFs öffnen sich über dem Ticket</strong>',
            'viewer_body' => 'Klicken Sie auf ein Bild oder ein PDF in einer Notiz oder in der Liste <strong>Anhänge</strong> des Tickets (Vorschaubild oder Zeile), und es öffnet sich in einem Fenster über dem Ticket &mdash; im selben Viewer wie im Modul Dateien. Das Ticket bleibt darunter genau dort, wo es war.',
            'viewer_window' => '<strong>Verschieben und Größe ändern</strong> &mdash; Ziehen Sie die Titelleiste, um das Fenster zu verschieben, und einen beliebigen Rand oder eine Ecke, um die Größe zu ändern; doppelklicken Sie auf die Titelleiste oder ziehen Sie sie an den oberen Bildschirmrand, um den Bildschirm auszufüllen. Das Bild oder PDF passt sich an, wenn sich die Fenstergröße ändert, bis Sie selbst zoomen &mdash; <strong>Einpassen</strong> gibt die Steuerung zurück. Wenn Sie mehrere öffnen, liegen sie nebeneinander.',
            'viewer_close' => '<strong>Schließen</strong> &mdash; das &times; in der Titelleiste oder <strong>Escape</strong> (schließt das vorderste Fenster). <strong>Herunterladen</strong> speichert die Datei. Auf einem Smartphone öffnet sich die Datei im Vollbild mit einer Zurück-Schaltfläche.',
            'viewer_other' => '<strong>Andere Dateien</strong> &mdash; Word-Dokumente, Tabellen und alles andere werden wie bisher heruntergeladen oder in einem neuen Tab geöffnet. Um das Bild oder PDF einer Notiz stattdessen in einem neuen Tab zu öffnen, klicken Sie mit gedrückter Strg-Taste darauf.',
            'paste_heading' => '<strong>Einen Screenshot in eine Notiz einfügen</strong>',
            'paste_body' => 'Kopieren Sie einen Screenshot, klicken Sie in das Feld <strong>Notiz hinzufügen</strong> und drücken Sie <strong>Strg+V</strong>. Das Bild wird an der Cursorposition eingefügt, mit Ihrem Text davor und danach, und bleibt nach dem Speichern an dieser Stelle. Klicken Sie darauf, um es in der Anzeige zu öffnen. Mit der <strong>Rücktaste</strong> entfernen Sie es vor dem Speichern.',
            'paste_shared' => '<strong>Geteilte Notizen teilen ihre Bilder</strong> &mdash; der Anfragende sieht sie im Portal an derselben Stelle. In einer internen Notiz sind sie so privat wie die Notiz selbst.',
            'paste_save' => '<strong>Erst beim Speichern wird etwas abgelegt</strong> &mdash; schließen Sie das Feld, verschwinden die Bilder mit ihm. Wird ein Bild abgelehnt, wird auch die Notiz nicht gespeichert, der Grund wird angezeigt, und Ihr Text bleibt im Feld.',
            'paste_text' => '<strong>Text bleibt Text</strong> &mdash; beim Einfügen aus Word, einer Webseite oder Excel kommen die Wörter ohne ihre Formatierung an. Die Schaltfläche <strong>Anhängen</strong> funktioniert weiterhin für alle anderen Dateien.',
            'rightclick_heading' => '<strong>Rechtsklick für Schnellaktionen</strong>',
            'rightclick_body' => 'Rechtsklicken Sie ein Ticket in der Liste, um ein Kontextmenü zu öffnen. Das Menü zeigt oben die Ticketreferenz an, damit Sie wissen, womit Sie arbeiten, und jede Aktion wirkt auf das rechtsgeklickte Ticket, <em>ohne</em> zu ändern, was gerade im Lesefenster geöffnet ist &mdash; nützlich, wenn Sie Ticket A lesen und Ticket B bewerten müssen, ohne Ihre Stelle zu verlieren.',
            'rightclick_status' => '<strong>Status festlegen &rarr;</strong> &mdash; Untermenü mit jedem aktiven Status und dessen Farbmuster. Ein Häkchen erscheint neben dem aktuellen Wert, wenn Sie das gerade geöffnete Ticket rechtsklicken. Die Auswahl aktualisiert das Ticket sofort, schreibt einen Eintrag ins Aktivitätsprotokoll, aktualisiert die Ordnerzähler und synchronisiert gegebenenfalls das Status-Dropdown im Lesefenster.',
            'rightclick_priority' => '<strong>Priorität festlegen &rarr;</strong> &mdash; dasselbe Untermenü-Muster, gespeist aus den aktiven Prioritäten mit deren Farbe als Muster. Die erste Zeile ist eine Option <em>(keine Priorität)</em> zum Entfernen der Zuweisung (Priorität kann leer sein).',
            'rightclick_assign' => '<strong>Zuweisen an &rarr;</strong> &mdash; Untermenü mit jedem geladenen Analysten mit grauem Initialen-Chip, plus eine Zeile <em>(nicht zugewiesen)</em> oben zum Entfernen. Die Auswahl setzt sowohl <code>assigned_analyst_id</code> als auch <code>owner_id</code>, sodass das Feld Eigentümer im Lesefenster synchron bleibt.',
            'rightclick_cmdb' => '<strong>CMDB-Objekt verknüpfen&hellip;</strong> &mdash; öffnet eine Auswahl mit Suche während der Eingabe. Klicken Sie auf ein Ergebnis, um es zu verknüpfen, und wählen Sie weiter &mdash; das Eingabefeld wird geleert und der Fokus für das nächste gesetzt, und ein Protokoll "Zuletzt verknüpft" im Dialogfeld zeigt Ihre laufende Liste grüner Häkchen.',
            'rightclick_time' => '<strong>Zeit erfassen&hellip;</strong> &mdash; öffnet ein Dialogfeld mit Minuten + einer Datum/Zeit-Auswahl (standardmäßig "jetzt", sodass Sie auch rückdatieren können) + einem optionalen Notizfeld.',
            'rightclick_phone' => '<strong>Auf dem Handy</strong> halten Sie ein Ticket eine halbe Sekunde lang gedrückt, um dasselbe Menü als Vollbildfeld zu öffnen. Eine Auswahl mit weiteren Optionen &mdash; Status setzen, Priorität setzen, Zuweisen an &mdash; schiebt sich zu diesen hinüber, mit <strong>Zurück</strong> für den Rückweg.',
            'rightclick_tip' => 'Ist das Ticket, mit dem Sie über das Kontextmenü arbeiten, zufällig dasselbe, das im Lesefenster geöffnet ist, aktualisiert sich der entsprechende Bereich dort (Status-/Prioritäts-Dropdowns, CMDB-Objekte, Zeiteinträge) automatisch, sobald das Dialogfeld geschlossen wird, damit die Oberfläche synchron bleibt.',
            'time_heading' => '<strong>Zeit erfassen</strong>',
            'time_body' => 'Die für ein Ticket aufgewendete Zeit wird in einem eigenen Bereich <strong>Zeiteinträge</strong> im Lesefenster erfasst, zwischen dem Panel der verknüpften CMDB-Objekte und dem Notizenpanel. Die Überschrift zeigt die Gesamtsumme (z. B. "Gesamt 2h 30m"), und jeder Eintrag darunter zeigt die aufgewendete Zeit, den Analysten, das Datum und alle hinzugefügten Notizen.',
            'time_step1' => '<strong>Formular im Fenster</strong> &mdash; geben Sie die aufgewendeten Minuten in das Zahlenfeld ein, optional eine kurze Beschreibung in das Notizfeld, und klicken Sie auf <strong>Hinzufügen</strong>. Der neue Eintrag erscheint sofort oben in der Liste mit Ihrem Namen und dem aktuellen Zeitstempel.',
            'time_step2' => '<strong>Rückdatieren per Rechtsklick</strong> &mdash; müssen Sie Zeit erfassen, die Sie zuvor zu erfassen vergessen haben, rechtsklicken Sie das Ticket in der Liste und wählen Sie <strong>Zeit erfassen&hellip;</strong>. Das Dialogfeld enthält eine Datum/Zeit-Auswahl, mit der Sie den Eintrag mit der tatsächlichen Zeit der geleisteten Arbeit versehen können.',
            'time_step3' => '<strong>Eigene Einträge löschen</strong> &mdash; neben Einträgen, die Sie selbst erfasst haben, erscheint eine kleine Schaltfläche &times;. Klicken Sie darauf (und bestätigen Sie), um sie weich zu löschen &mdash; die Zeile bleibt zu Auditzwecken mit <code>is_active = 0</code> in der Datenbank, verschwindet aber aus der Liste. Sie können keine Einträge anderer Analysten löschen.',
            'time_tip1' => 'Zeiten werden als reine Minutenzahl gespeichert (45 Min., 90 Min. usw.) und in der Oberfläche als <code>45m</code> oder <code>1h 30m</code> dargestellt &mdash; fein genug für kurze Korrekturen, ohne das Rundungsproblem von Dezimalstunden.',
            'time_tip2' => 'Jede Feldänderung wird im Aktivitätsprotokoll des Tickets erfasst. Sie können jederzeit nachvollziehen, wer wann was geändert hat, was für die Audit-Konformität und die Übergabe zwischen Analysten unerlässlich ist.',
        ],
        'comments' => [
            'heading' => 'Kommentare &amp; Anhänge',
            'intro' => 'Das Aktivitätsprotokoll ist das Herzstück jedes Tickets. Es erfasst jede Aktion &mdash; Kommentare, Feldänderungen, gesendete E-Mails und angehängte Dateien &mdash; in einer chronologischen Zeitleiste, die die vollständige Geschichte einer Supportanfrage erzählt.',
            'adding_heading' => '<strong>Kommentare hinzufügen</strong>',
            'step1' => '<strong>Ticket öffnen</strong> &mdash; klicken Sie ein Ticket im Posteingang an, um dessen Lesefenster zu laden. Scrollen Sie nach unten, um das vollständige Aktivitätsprotokoll und das Kommentarfeld darunter zu sehen.',
            'step2' => '<strong>Notiz schreiben</strong> &mdash; nutzen Sie die Schaltfläche Notiz hinzufügen, um den Kommentar-Editor zu öffnen. Notizen sind standardmäßig intern und nur für Analysten des Service Desks sichtbar.',
            'step3' => '<strong>Per E-Mail antworten oder weiterleiten</strong> &mdash; nutzen Sie die Aktionen Antworten oder Weiterleiten, um eine Nachricht an den Endbenutzer oder einen Dritten zu senden. Die E-Mail wird zusammen mit dem gesendeten Nachrichteninhalt im Aktivitätsprotokoll erfasst.',
            'files_heading' => '<strong>Dateianhänge</strong>',
            'files_body' => 'Hängen Sie Screenshots, Protokolle, Dokumente oder jede unterstützende Datei direkt an ein Ticket an. Dateien können in die Ablagezone für Anhänge gezogen oder über den Dateibrowser ausgewählt werden. Anhänge werden auf dem Server gespeichert und mit dem Aktivitätsprotokoll des Tickets verknüpft, sodass nichts verloren geht.',
            'audit_heading' => '<strong>Audit-Protokollierung</strong>',
            'export_heading' => '<strong>Fallberichte</strong>',
            'export_body' => 'Für eine Prüfung oder einen Auditor macht <strong>Exportieren</strong> in der Symbolleiste des Tickets aus dem Ticket und seinen Aufgaben einen druckbaren Bericht - siehe <a href="#case-reports">Fallberichte</a>.',
            'audit_body' => 'Das Aktivitätsprotokoll erfasst automatisch jede Aktion, ohne dass Analysten eingreifen müssen. Wird eine Priorität von Mittel auf Hoch geändert, werden alter und neuer Wert erfasst. Wird ein Ticket neu zugewiesen, werden sowohl der bisherige als auch der neue Analyst protokolliert. So entsteht eine vollständige, manipulationssichere Historie, die die Audit-Anforderungen von ITIL erfüllt und Managern hilft, nachzuvollziehen, wie Tickets bearbeitet werden.',
            'tip' => 'Beim Antworten per E-Mail können Sie im selben Vorgang Cc-Empfänger hinzufügen und Dateien anhängen. Der gesamte E-Mail-Verlauf wird im Aktivitätsprotokoll des Tickets zusammengeführt, sodass die gesamte Kommunikation an einem Ort bleibt.',
        ],
        'ai' => [
            'heading' => 'KI-Werkzeuge',
            'intro' => 'Zwei von Claude angetriebene Funktionen sind in den Ticket-Workflow eingebettet: <strong>Antwort-Bereinigung</strong> formt einen groben Entwurf in eine ordentlich formatierte E-Mail um, und <strong>KI fragen</strong> durchsucht die Wissensdatenbank in natürlicher Sprache mithilfe des Ticketkontexts.',
            'cleanup_heading' => '<strong>Antwort-Bereinigung &mdash; Schaltfläche ✨ im Antwort-Editor</strong>',
            'cleanup_body' => 'Tippen Sie einen groben Entwurf in eine Antwort (oder einfach Stichpunkte wie *"Druckdienst neu starten, Screenshot für sie machen"*) und klicken Sie auf die Schaltfläche <strong>✨ Bereinigen</strong>. Claude formt sie in eine ordentlich formatierte E-Mail um &mdash; fügt eine Anrede <em>Sehr geehrte(r) [name],</em> für den Anfragenden hinzu, korrigiert die Grammatik, wendet den konfigurierten Ton an und schließt mit <em>Mit freundlichen Grüßen,</em>. Der Prompt ist so eingeschränkt, dass er KEINE technischen Details erfindet, KEINE Entschuldigungen erdichtet und den Inhalt nicht über das von Ihnen Geschriebene hinaus aufbläht.',
            'cleanup_streams' => '<strong>Live-Streaming</strong> &mdash; die Umformulierung erscheint im Editor, während Claude sie generiert (kein Warten vor einem Ladesymbol).',
            'cleanup_undo' => '<strong>Rückgängig-Link für 30 Sekunden</strong> &mdash; falls Claude die Umformulierung verpatzt, erscheint 30 Sekunden nach Abschluss ein kleiner <em>Rückgängig</em>-Link unter dem Editor, der den ursprünglichen Entwurf wiederherstellt.',
            'cleanup_tone' => '<strong>Nach Ton</strong> &mdash; drei Ton-Voreinstellungen konfigurierbar unter <strong>Einstellungen &rarr; Antwort-Bereinigung</strong>: <em>Freundlich</em> (Standard), <em>Formell</em>, <em>Kurz</em>. Wählen Sie, was zum Hausstil Ihres Teams passt.',
            'cleanup_key' => '<strong>Eigener API-Schlüssel</strong> &mdash; getrennt vom Anthropic-Schlüssel der KI-Funktionen für RFP / Wissensdatenbank / Workflow, sodass die Nutzung im Anthropic-Abrechnungsdashboard als eigene Zeile erscheint. Konfiguriert unter <strong>Einstellungen &rarr; Antwort-Bereinigung</strong>.',
            'cleanup_tip' => 'Bereinigung eignet sich am besten für routinemäßige Antworten im Stil "Ich habe X versucht, bitte versuchen Sie Y". Für lange, differenzierte Nachrichten sollten Sie diese selbst schreiben &mdash; die KI ist stark bei der Struktur, kennt aber Ihre konkrete Umgebung nicht.',
            'ask_heading' => '<strong>KI fragen &mdash; Schaltfläche 🤖 in der Ticket-Symbolleiste</strong>',
            'ask_body' => 'Klicken Sie auf die Schaltfläche <strong>KI fragen</strong> (🤖) in der Ticket-Symbolleiste, um ein seitlich einblendendes Chat-Panel zu öffnen, das Betreff, Text und Kontext des Leseraums des geöffneten Tickets kennt. Stellen Sie Fragen wie *"Hatten wir das schon einmal?"* oder *"Was ist die übliche Lösung für diesen Fehler?"*, und es durchsucht die <a href="../knowledge/" style="color:#0078d4;">Wissensdatenbank</a> semantisch (über Claude + OpenAI-Embeddings) und antwortet mit relevanten Artikeln samt direkten Links zum Öffnen.',
            'ask_context' => '<strong>Kontextbewusst</strong> &mdash; das Panel weiß, welches Ticket Sie gerade ansehen, sodass Sie allgemeine Fragen stellen können und es den relevanten Kontext selbst ermittelt.',
            'ask_linked' => '<strong>Verlinkte Artikel</strong> &mdash; Vorschläge sind anklickbar und öffnen den passenden Wissensartikel in einem neuen Tab.',
            'ask_shared' => '<strong>Gemeinsam mit dem Wissensdatenbank-Modul genutzt</strong> &mdash; die KI verwendet denselben Schlüssel und dasselbe Modell wie die KI-Suche der Wissensdatenbank, sodass eine einmalige Konfiguration beides abdeckt. Details zur Einrichtung finden Sie in der Hilfe zum Wissensdatenbank-Modul.',
        ],
        'csat' => [
            'heading' => 'Kundenzufriedenheitsumfragen (CSAT)',
            'intro' => 'Senden Sie dem Anfragenden per E-Mail eine 1&ndash;5-Zufriedenheitsumfrage, wenn ein Ticket gelöst wird, erfassen Sie die Antwort auf einer Landingpage ohne Anmeldung, und verfolgen Sie Trends pro Analyst auf einer eigenen Auswertungsseite.',
            'modes_heading' => '<strong>Zwei Auslösemodi &mdash; wählen Sie einen</strong>',
            'mode_auto' => '<strong>Automatisch beim Schließen</strong> &mdash; die Umfrage wird automatisch eingereiht, sobald ein Ticket in einen geschlossenen Status wechselt. Der Analyst muss nichts tun &mdash; die Lösung löst die Umfrage aus.',
            'mode_manual' => '<strong>Nur manuell</strong> &mdash; der Analyst klickt bei Bedarf auf die Schaltfläche ⭐ <strong>Rückmeldung</strong> in der Ticket-Symbolleiste. Nützlich, wenn Sie lieber von Fall zu Fall entscheiden möchten, ob eine Rückmeldung angefragt wird.',
            'switch_note' => 'Sie verwenden CSAT überhaupt nicht? Schalten Sie es unter <strong>System &rarr; Module &rarr; Verfügbarkeit &rarr; Ticketfunktionen</strong> aus, und es verschwindet: keine Umfragen, keine CSAT-Seite, keine Schaltfläche Feedback anfordern, und alte Umfragelinks weisen darauf hin, dass kein Feedback mehr erfasst wird. Nichts wird gelöscht.',
            'mode_off' => '<strong>Aus</strong> &mdash; Funktion deaktiviert; es werden keine Umfrage-E-Mails versendet.',
            'modes_choose' => 'Auswahl unter <strong>Tickets &rarr; Einstellungen &rarr; CSAT</strong>. Die manuelle Schaltfläche funktioniert auch im Modus <em>Automatisch</em> weiterhin &mdash; Analysten können bei Bedarf erneut um Rückmeldung zu einem bereits befragten Ticket bitten.',
            'template_heading' => '<strong>Die E-Mail-Vorlage</strong>',
            'template_body' => 'Der Inhalt der Umfrage-E-Mail stammt aus dem bestehenden Reiter <strong>E-Mail-Vorlagen</strong> &mdash; erstellen Sie eine Vorlage mit dem Ereignis <strong>CSAT-Umfrage</strong> (das neue Ereignis neben <em>Ticket zugewiesen</em> / <em>Ticket geschlossen</em>) und betten Sie den Merge-Code <code>[csat_link]</code> dort ein, wo die Bewertungs-URL erscheinen soll. Die üblichen Merge-Codes (<code>[requester_name]</code>, <code>[ticket_reference]</code>, <code>[analyst_name]</code>) stehen wie gewohnt zur Verfügung.',
            'template_tip' => 'Existiert keine aktive CSAT-Vorlage, verweigert die Schaltfläche <em>Rückmeldung</em> mit einer klaren Fehlermeldung, und die automatische Auslösung wird stillschweigend übersprungen &mdash; es können nie tote Umfrage-Links entstehen.',
            'survey_heading' => '<strong>Die Umfrageseite</strong>',
            'survey_body' => 'Der Anfragende klickt auf den Link in der E-Mail und gelangt auf eine Seite ohne Anmeldung mit einer 1&ndash;5-Auswahl plus einem optionalen Kommentarfeld. Zwei visuelle Stile konfigurierbar unter <strong>Einstellungen &rarr; CSAT</strong>:',
            'survey_stars' => '<strong>Sterne</strong> &mdash; klassisches Verhalten mit Füllung beim Hover in Reihenfolge. Beim Hover über Stern Nr. 3 füllen sich Nr. 1+2+3 in Gold. Klick zum Festlegen.',
            'survey_emojis' => '<strong>Emojis</strong> &mdash; 5 Gesichter 😡 🙁 😐 🙂 😀 starten in Graustufen mit 40% Deckkraft; das mit Hover oder Auswahl versehene kehrt in voller Farbe bei 1,25-facher Größe zurück. Klick zum Festlegen.',
            'survey_store' => 'Beide Modi speichern dieselbe 1&ndash;5-Zahl, sodass Dashboards und Durchschnittswerte unabhängig vom verwendeten Stil identisch funktionieren. Die Umfrage-URL ist einmalig verwendbar &mdash; nach dem Absenden verweigert derselbe Link eine erneute Übermittlung.',
            'chat_heading' => '<strong>Chat-Kunden in ihrem Chat fragen</strong>',
            'chat_body' => 'Ist <strong>Chat-Kunden in ihrem Chat fragen</strong> angehakt, wird ein Kunde, der über WhatsApp, Telegram, Slack, Microsoft Teams oder Mattermost geschrieben hat, in diesem Chat statt per E-Mail gefragt &mdash; mit fünf Schaltflächen bei Telegram, Teams und Mattermost, anderswo mit „Antworten Sie mit einer einzelnen Ziffer“. Die Antwort fließt in dieselben Ergebnisse wie eine per E-Mail versendete Umfrage.',
            'chat_rules' => 'WhatsApp wird nur gefragt, solange das 24-Stunden-Antwortfenster offen ist; außerhalb davon, oder wenn die Chat-Nachricht nicht gesendet werden kann, wird stattdessen die E-Mail-Umfrage verwendet. Eine Ziffer zählt nur dann als Bewertung, wenn sie direkt auf die Frage folgt &mdash; im selben Chat, innerhalb einer Woche und bevor der Kunde etwas anderes geschrieben hat &mdash; sodass eine „3“ als Antwort auf die Frage eines Analysten eine Nachricht bleibt. Nach einem Upgrade aus; bei einer Neuinstallation an.',
            'analytics_heading' => '<strong>Die Auswertungsseite</strong>',
            'analytics_body' => 'Klicken Sie auf die Navigationsschaltfläche ⭐ <strong>CSAT</strong> (zwischen Dienstplan und Einstellungen), um das Auswertungs-Dashboard unter <code>tickets/csat/</code> zu öffnen. Zeitfenster wählbar: 7 / 30 / 90 / 365 Tage.',
            'card_kpi_title' => 'KPI-Kacheln',
            'card_kpi_body' => 'Durchschnittsbewertung (von 5), Anzahl der Antworten, Antwortquote (Antworten ÷ Gesendet)',
            'card_dist_title' => 'Bewertungsverteilung',
            'card_dist_body' => 'Balkendiagramm der Bewertungen 1–5 mit genauen Anzahlen und Prozentwerten',
            'card_leader_title' => 'Rangliste pro Analyst',
            'card_leader_body' => 'Durchschnittsbewertung + Antwortanzahl pro Analyst, sortiert nach Durchschnitt absteigend. Nützlich für Entwicklungsgespräche',
            'card_recent_title' => 'Letzte Antworten',
            'card_recent_body' => 'Die Bewertungen, neueste zuerst, 25 pro Seite, mit ihren Freitextkommentaren und dem Kunden, der sie abgegeben hat, verknüpft mit dem Ursprungsticket',
            'analytics_filters' => 'Schränken Sie die Seite mit den Filtern unter der Überschrift ein: ein Datumsbereich <strong>Von / Bis</strong> (anstelle der Tagesschaltflächen), ein Bereich <strong>Bewertung</strong> (Positiv 4-5, Neutral 3, Negativ 1-2), ein <strong>Analyst</strong> und ein <strong>Kunde</strong>. Analyst und Kunde schränken jede Zahl auf der Seite ein; der Bewertungsbereich schränkt nur die Liste der Rückmeldungen ein, damit der Durchschnitt weiterhin aussagekräftig bleibt. Auf dem Handy liegen die Filter hinter der Schaltfläche <strong>Filter</strong> am unteren Bildschirmrand. Eine gefilterte Seite kann als Lesezeichen gespeichert werden.',
            'analytics_company' => 'Jede Zahl folgt dem <strong>Unternehmenswechsler</strong> in der Kopfzeile: dem ausgewählten Unternehmen oder, unter <strong>Alle Unternehmen</strong>, jedem Unternehmen, das Sie sehen können.',
            'analytics_tip' => 'Die Zuordnung pro Analyst übersteht eine Ticket-Neuzuweisung, weil die Analysten-ID beim Versand in die Umfragezeile geschrieben wird, nicht live nachgeschlagen. Wird ein Ticket vor dem Schließen mehrfach weitergereicht, gehört die Bewertung dem Analysten, der es tatsächlich geschlossen hat.',
            'one_heading' => '<strong>Eine Umfrage pro Ticket</strong>',
            'one_body' => 'Ist <em>Eine Umfrage pro Ticket</em> aktiv (Standard), erhält ein wieder geöffnetes und dann erneut geschlossenes Ticket nur dann eine weitere Umfrage, wenn ein Analyst sie manuell auslöst &mdash; das verhindert Umfrage-Spam bei einem Ticket, das ständig zwischen den Status wechselt. Schalten Sie es aus, wenn jedes Schließen eine neue Umfrage auslösen soll.',
        ],
        'users' => [
            'heading' => 'Benutzerverwaltung',
            'intro' => 'Die Navigationsschaltfläche <strong>Benutzer</strong> öffnet <code>tickets/users.php</code> &mdash; ein Verzeichnis jedes Endbenutzers (der Personen, die Tickets erstellen, nicht der Analysten) samt Tickethistorie.',
            'p_intro' => 'Benutzer gelangen auf vier reaktive Wegen ins System &mdash; Selbstregistrierung im Portal, eine eingehende E-Mail eines neuen Absenders, den Postfach-Abfragedienst oder die Workflow-Engine, die einen aus einem ausgelösten Ticket erstellt. Das deckt die meisten Fälle ab, aber die Benutzerseite erlaubt Ihnen auch, einen Benutzer <strong>im Voraus anzulegen</strong> (z. B. einen neuen Mitarbeiter, der bald Zugang benötigt), sowie bestehende Zeilen zu <strong>bearbeiten</strong> oder zu <strong>löschen</strong>.',
            'add_heading' => '<strong>Benutzer hinzufügen</strong>',
            'add_body' => 'Die Schaltfläche <strong>Hinzufügen</strong> in der Kopfzeile der Benutzerliste öffnet den Personeneditor. Es ist derselbe Editor, den <strong>Assets &rarr; Benutzer</strong> öffnet, sodass eine Person auf jedem Bildschirm auf dieselbe Weise hinzugefügt und geändert wird:',
            'add_email' => '<strong>E-Mail</strong> &mdash; optional, da Personen, die sich über ein Verzeichnis anmelden, möglicherweise kein Postfach haben; sie werden stattdessen über ihren Anmeldenamen gefunden. Geben Sie entweder eine E-Mail-Adresse oder einen Anzeigenamen an. Eine Adresse muss eindeutig sein und darf nicht zu einem Analysten gehören.',
            'add_names' => '<strong>Anzeigename / bevorzugter Name</strong> &mdash; optional. Der bevorzugte Name ist die Anrede, mit der sich der Benutzer in E-Mails begrüßt sieht (z. B. <em>"Max"</em> statt <em>"Max Mustermann"</em>).',
            'add_password' => '<strong>Passwort</strong> &mdash; optional. Wird es leer gelassen, entsteht ein <em>passwortloses</em> Konto &mdash; genau der Zustand, in dem Benutzer aus eingehenden Tickets starten. Der Benutzer kann das Konto später über den Registrierungsablauf des Self-Service-Portals übernehmen, indem er sein eigenes Passwort festlegt.',
            'add_details' => '<strong>Position, Abteilung, Standort, Telefon, Mobil, Personalnummer und Vorgesetzte Person</strong> &mdash; alles optional und alles Angaben zur <em>Person</em> statt zum Login. Es lohnt sich, sie auszufüllen: Der <strong>Standort</strong> verrät, an welchem Ort jemand ist, bevor Sie nach der Person suchen, die <strong>Vorgesetzte Person</strong> hält die Berichtslinie fest (tippen Sie einen Teil des Namens, um sie zu finden), und die <strong>Personalnummer</strong> ist der Verknüpfungsschlüssel beim Abgleich mit einem Gehaltsabrechnungssystem, das von E-Mail-Adressen nichts weiß. Bei einem Import aus einem Verzeichnis kommen alle diese Angaben bereits ausgefüllt an. Ein CardDAV-Adressbuch füllt alles außer Personalnummer und Vorgesetzter Person aus, da eine Kontaktkarte dafür keinen Platz hat.',
            'managed_heading' => '<strong>Personen, die anderswo gepflegt werden</strong>',
            'source_body' => '<strong>Woher eine Person stammt</strong> wird in ihren Angaben genannt (<em>Angaben von: Contoso AD - Verzeichnis</em>), und der Filter <strong>Quelle</strong> unter dem Suchfeld listet nur die Personen aus einem Verzeichnis oder Adressbuch, oder nur die in FreeITSM hinzugefügten, mit einer Anzahl daneben. Er erscheint, sobald jemand mit einer Quelle verknüpft ist.',
            'add_book_body' => '<strong>Zum Adressbuch hinzufügen.</strong> Jemand, der eine E-Mail geschickt hat, existiert hier, aber in keinem Adressbuch. Hat ein Administrator <em>Analysten dürfen Personen zu diesem Adressbuch hinzufügen</em> eingeschaltet (System &rarr; Authentifizierung, am Adressbuch), erhält diese Person eine Schaltfläche <strong>Zum Adressbuch hinzufügen</strong> neben Bearbeiten. Sie fragt zuerst nach und zeigt, was auf die Karte kommt, legt dann den Kontakt an und verknüpft ihn &mdash; dieselbe Person, keine Kopie. Sie fügt niemanden hinzu, dessen E-Mail-Adresse das Buch bereits hat (führen Sie stattdessen den Import aus), und sie stellt sicher, dass der nächste Import den neuen Kontakt erfasst, oder nimmt die Karte sonst wieder heraus.',
            'managed_body' => 'Wurde eine Person importiert &mdash; aus LDAP oder Active Directory, oder aus einem CardDAV-Adressbuch &mdash;, sind die Angaben, die diese Quelle besitzt, <strong>schreibgeschützt</strong> und im Dialog ausgegraut. Woher sie stammt, ist die maßgebliche Quelle, und der nächste Import würde alles hier Eingetragene überschreiben, daher wird das Speichern von vornherein verweigert, statt es anzunehmen und eine Stunde später stillschweigend rückgängig zu machen. <strong>Welche</strong> Angaben betroffen sind, hängt von der Quelle ab: Ein Verzeichnis besitzt alle sieben, ein Adressbuch dagegen fünf &mdash; es hat keinen Platz für eine Personalnummer oder eine Berichtslinie, daher bleiben diese beiden Ihnen zum Ausfüllen überlassen. Und ist beim Adressbuch <em>Änderungen zurückschreiben</em> eingeschaltet, ist keines davon gesperrt: Was Sie eingeben, wird an die Kontaktkarte gesendet, sodass es beim nächsten Import nichts rückgängig zu machen gibt. Alles andere am Datensatz, einschließlich Unternehmen und Passwort, bleibt immer bearbeitbar.',
            'edit_heading' => '<strong>Benutzer bearbeiten</strong>',
            'edit_body' => 'Wählen Sie einen Benutzer aus der Liste und klicken Sie dann in der Detailkopfzeile auf <strong>Bearbeiten</strong>. Derselbe Editor, vorausgefüllt. Wenn Sie ohne Passwort speichern, bleibt der vorhandene Hash unverändert; wenn Sie eines angeben, wird es zurückgesetzt. Ist die vorgesetzte Person jemand aus einem Unternehmen, das Sie nicht sehen können, weist das Feld darauf hin und die Person bleibt eingetragen, sofern Sie nicht jemand anderen wählen.',
            'signin_body' => '<strong>Meldet sich an mit</strong> zeigt, mit welchem Single-Sign-On-Anbieter eine Person verknüpft ist. <strong>Verknüpfung aufheben</strong> daneben entfernt nach einer Bestätigung diese Verknüpfung, sodass die nächste Anmeldung neu beginnt &mdash; für jemanden, der zu einem anderen Anbieter gewechselt ist oder mit dem falschen Konto verknüpft wurde. Das wird für Personen, die über eine Verzeichnissynchronisierung verwaltet werden, nicht angeboten, da sie einfach erneut verknüpft würden.',
            'company_body' => '<strong>Unternehmen</strong> erscheint, wenn Sie mehr als eines haben. Bei einer neuen Person wird das Unternehmen aus der E-Mail-Adresse abgeleitet, wenn Sie das Feld leer lassen; bei einer bestehenden Person bedeutet leer kein Unternehmen, und ihre Tickets gehen in die Triage.',
            'managers_heading' => '<strong>Führungskräfte</strong>',
            'managers_body' => 'Eine Person kann im Self-Service-Portal zur <strong>Führungskraft</strong> gemacht werden: Sie erhält einen Reiter <strong>Team-Tickets</strong> mit den Tickets der Personen, die sie führt. Das ist aus, bis ein Administrator es unter <strong>System &rarr; Führungskräfte</strong> einschaltet; dort wird auch festgelegt, ob Führungskräfte auf diese Tickets antworten oder sie schließen dürfen und was sie von einem vertraulichen Ticket sehen (standardmäßig nichts).',
            'managers_sources' => 'Jemand ist auf zwei Arten Führungskraft, beide gleichzeitig: als <strong>Vorgesetzte Person</strong> in den Datensätzen anderer (von Hand oder aus Ihrem Verzeichnis) und durch <strong>Führungszuordnungen</strong>, die für sie eingerichtet sind. Klicken Sie neben Bearbeiten auf <strong>Zugriff als Führungskraft</strong>, um eine Vollbildseite für diese Person zu öffnen. Dort können Sie ihr alle, bestimmte Personen, Personengruppen, Abteilungen oder die gesamte Berichtslinie zuordnen und Personen <strong>ausschließen</strong> &mdash; ein Ausschluss hat immer Vorrang, auch vor dem Feld „Vorgesetzte Person“. Die Seite zeigt, wie viele Personen sie sehen kann, und listet sie auf, berechnet so, als wären Führungskräfte bereits eingeschaltet, damit Sie vor dem Einschalten prüfen können. Klicken Sie in dieser Liste auf eine Person, um zu sehen, <strong>warum</strong> die Führungskraft sie sehen kann und wie Sie das beenden.',
            'managers_rules' => 'Eine Führungskraft sieht immer nur Personen aus dem eigenen Unternehmen, nie sich selbst und nach dem Ausscheiden gar nichts mehr. Abteilungen werden anhand des bei jeder Person eingetragenen Namens zugeordnet, sodass eine umbenannte Abteilung nicht mehr passt &mdash; die Seite und System &rarr; Führungskräfte warnen vor einer Abteilungszuordnung, die auf niemanden zutrifft. Standardmäßig können nur Administratoren Führungszuordnungen ändern; System &rarr; Führungskräfte kann das für alle öffnen, die Personen bearbeiten dürfen.',
            'delete_heading' => '<strong>Benutzer löschen</strong>',
            'delete_body' => 'Die Schaltfläche <strong>Löschen</strong> ist <strong>FK-sicher</strong>: Sie verweigert den Vorgang, wenn der Benutzer bei einem Ticket als Anfragender geführt wird oder Zeilen in <code>users_assets</code> hat, und gibt eine klare Meldung aus: <em>"Löschen nicht möglich: Dieser Benutzer ist Anfragender bei N Ticket(s). Weisen Sie diese Tickets neu zu oder schließen Sie sie zuerst."</em> Die Audit-Historie kann nie stillschweigend beschädigt werden.',
            'tip' => 'Bei allen Feldern des Dialogfelds ist die automatische Vervollständigung des Browsers deaktiviert (einschließlich <code>autocomplete="new-password"</code> beim Passwortfeld), damit die eigenen gespeicherten Zugangsdaten des Analysten nicht in ein Formular vorgeschlagen werden, dessen gesamter Zweck darin besteht, den Datensatz <em>einer anderen Person</em> anzulegen.',
            'groups_heading' => '<strong>Gruppen</strong>',
            'groups_body' => 'Der Reiter <strong>Gruppen</strong> neben <strong>Personen</strong> enthält benannte Personengruppen &mdash; Analysten und Self-Service-Portalbenutzer zusammen in derselben Gruppe. Eine Gruppe wird hier einmal angelegt und dann in ganz FreeITSM verwendet, sodass Sie ihr Zugriff auf einen Wissensordner geben oder einen Schulungskurs zuweisen können, ohne dieselbe Liste zweimal aufzubauen.',
            'groups_make' => '<strong>Legen Sie eine an</strong> mit <strong>Hinzufügen</strong> auf dem Reiter Gruppen: ein Name und eine Beschreibung, die sich zu füllen lohnt, denn die nächste Person muss erkennen können, wofür die Gruppe gedacht ist.',
            'groups_add' => '<strong>Fügen Sie Personen hinzu</strong>, indem Sie nach ihnen suchen &mdash; die Suche findet Analysten und Portalbenutzer gemeinsam, sodass Sie nicht wissen müssen, um welche Art es sich handelt.',
            'groups_expiry' => '<strong>Geben Sie einer Mitgliedschaft ein Enddatum</strong>, wenn der Zugriff befristet ist. Drei Techniker, die zwei Wochen vor Ort sind, erhalten einen letzten Tag und scheiden von selbst aus der Gruppe aus, wenn dieser vorbei ist. Eine abgelaufene Mitgliedschaft bleibt auf der Liste, als abgelaufen markiert, sodass Sie weiterhin sehen können, wer Zugriff hatte und bis wann.',
            'groups_uses' => '<strong>Wofür eine Gruppe gut ist:</strong> Zugriff auf einen Wissensordner gewähren und einer ganzen Reihe von Personen auf einmal eine LMS-Schulung zuweisen. Änderungen an der Mitgliedschaft wirken sofort &mdash; danach muss nichts erneut angewendet werden.',
            'groups_admin' => '<strong>Jeder mit dem Ticket-Modul kann die Gruppen sehen; ändern kann sie nur ein Administrator.</strong> Jemanden zu einer Gruppe hinzuzufügen, kann ihm auch Zugriff auf einen eingeschränkten Wissensordner geben — es ist also eine Zugriffsgewährung, keine reine Ablage.',
        ],
        'dash' => [
            'heading' => 'Dashboard',
            'intro' => 'Das Ticket-Dashboard bietet Auswertungen auf einen Blick mit anpassbaren Chart.js-Widgets. Jeder Analyst hat sein eigenes Dashboard-Layout, sodass Sie sich auf die für Ihre Rolle relevanten Kennzahlen konzentrieren können &mdash; ob persönliche Auslastung, Team-Durchsatz oder SLA-Einhaltung.',
            'step1' => '<strong>Die Bibliothek öffnen</strong> &mdash; klicken Sie auf Dashboard bearbeiten, um in den Bearbeitungsmodus zu wechseln, und durchsuchen Sie dann die Widget-Bibliothek. Wählen Sie aus vorgefertigten Widgets oder erstellen Sie ein eigenes, indem Sie einen Diagrammtyp und die zu aggregierende Dateneigenschaft auswählen.',
            'step2' => '<strong>Widgets hinzufügen</strong> &mdash; klicken Sie auf die Schaltfläche + bei einem beliebigen Widget in der Bibliothek, um es Ihrem Dashboard hinzuzufügen. Es erscheint sofort und zeigt Live-Daten aus Ihrer Ticketdatenbank an.',
            'step3' => '<strong>Konfigurieren</strong> &mdash; klicken Sie auf das Zahnrad-Symbol eines Widgets, um Titel, Diagrammtyp (Balken, Kreis, Ring, Linie, gestapelte Balken, Mehrfachlinie), Datumsbereichsfilter, Abteilungsfilter und Zeitgruppierung (täglich, wöchentlich, monatlich) anzupassen.',
            'step4' => '<strong>Anordnen</strong> &mdash; ziehen Sie Widgets per Drag-and-Drop, um sie neu anzuordnen. Ihr Layout wird pro Analyst gespeichert, sodass es sitzungsübergreifend erhalten bleibt.',
            'examples' => 'Gängige Widget-Beispiele sind: <strong>Tickets nach Status</strong> (Ringdiagramm mit offen vs. gelöst vs. geschlossen), <strong>Tickets nach Priorität</strong> (Balkendiagramm des Volumens nach Schweregrad), <strong>Wöchentliches Volumen</strong> (Liniendiagramm neuer Tickets über die Zeit), und <strong>Analystenauslastung</strong> (gestapelte Balken mit den aktiven Tickets jedes Analysten).',
            'tip' => 'Nutzen Sie Datumsbereichsfilter bei einzelnen Widgets, um die aktuelle Leistung mit früheren Zeiträumen zu vergleichen. Eine Ansicht "Dieser Monat vs. Letzter Monat" hilft Ihnen beispielsweise, Trends im Ticketaufkommen frühzeitig zu erkennen.',
        ],
        'cal_rota' => [
            'switch_note' => 'Sie verwenden den Bereitschaftsplan nicht? Schalten Sie ihn unter <strong>System &rarr; Module &rarr; Verfügbarkeit &rarr; Ticketfunktionen</strong> aus - die Seite, ihre Einstellungen und das <em>Wer hat Bereitschaft</em> des War-Room-Bots entfallen, und nichts wird gelöscht.',
            'heading' => 'Kalender &amp; Dienstplan',
            'intro' => 'Zwei Planungswerkzeuge helfen Ihrem Team, organisiert zu bleiben: ein Ticketkalender, der die Auslastung über die Zeit visualisiert, und ein Dienstplan für die Verwaltung von Schichten und Bereitschaftsdiensten.',
            'cal_heading' => '<strong>Kalenderansicht</strong>',
            'cal_body' => 'Der Kalender zeigt jedes Ticket mit gesetztem <code>work_start_datetime</code> (über das Dialogfeld <em>Zeit erfassen</em> / <em>Planen</em> per Rechtsklick) als farbigen Block zur geplanten Zeit an. Rote Blöcke haben die Priorität <em>Hoch</em>, grüne <em>Niedrig</em>, blau ist alles andere. Nutzen Sie <em>Heute</em>, die Pfeile <em>&lt;</em> / <em>&gt;</em> und den Umschalter <strong>Monat / Woche / Tag</strong> rechts in der Kopfzeile zum Navigieren &mdash; <em>Zurück</em> / <em>Weiter</em> springt je nach aktiver Ansicht um einen Monat, eine Woche oder einen Tag.',
            'cal_scope' => '<strong>Meine oder Alle.</strong> Der Kalender öffnet sich mit Ihrer eigenen geplanten Arbeit, mit einem Schalter <strong>Alle</strong> neben den Ansichts-Schaltflächen; Ihre Wahl wird gemerkt. Bei Alle trägt jedes Ticket eine <strong>Farbe für den jeweiligen Eigentümer</strong>, mit einer Legende, die die tatsächlich angezeigten Personen benennt, und ein Ticket zu überfahren zeigt Ihnen, wem es gehört, ohne wegzusehen. Nichts wird vor irgendjemandem verborgen &mdash; es sind dieselben Tickets, die der Posteingang bereits auflistet.',
            'cal_edit' => '<strong>Arbeit neu anordnen.</strong> <strong>Ziehen Sie ein Ticket</strong> auf einen anderen Tag oder eine andere Zeit: In der Monatsansicht behält es seine Uhrzeit, in der Wochen- und Tagesansicht übernimmt es die Uhrzeit, an der Sie es ablegen, gerundet auf die nächste Viertelstunde. Seine Dauer ändert sich nie &mdash; Ziehen bedeutet <em>fang dann an</em>, nicht <em>mach es länger</em>. Oder <strong>klicken Sie ein Ticket an</strong>, um es zu öffnen, wo Sie Datum, Uhrzeit, Dauer und die Ganztags-Einstellung ändern oder die Terminierung ganz entfernen können. Der Kalender <strong>aktualisiert sich außerdem alle paar Sekunden</strong> selbst, sodass eine Terminierung durch eine Kollegin erscheint, ohne dass Sie neu laden müssen &mdash; und er hält sich zurück, solange Sie ein Ticket geöffnet haben oder gerade ziehen.',
            'cal_month' => '<strong>Monatsansicht</strong> &mdash; das klassische 6-zeilige Raster mit einer Wochentag-Kopfleiste; jede Tageszelle zeigt bis zu drei Ticket-Chips mit ihrer Startzeit sowie einen Link <em>+N weitere</em>, der zur Tagesansicht für dieses Datum führt. Heute ist hervorgehoben.',
            'cal_week' => '<strong>Wochenansicht</strong> &mdash; Mo&ndash;So oben quer über eine 24-Stunden-Zeitleiste. Tickets erscheinen als 1-Stunden-Blöcke in Farbe zu ihrer Startzeit. Die Spalte des heutigen Tages ist hervorgehoben; die Wochentag-Kopfleiste bleibt fest, während das Stundenraster scrollt.',
            'cal_day' => '<strong>Tagesansicht</strong> &mdash; eine einzelne, hohe Spalte für den gewählten Tag mit derselben 24-Stunden-Zeitleiste. Tickets erscheinen als größere Blöcke mit <code>Ticketnummer &mdash; Betreff</code> und Startzeit; klicken Sie eines an, um die Details zu öffnen.',
            'rota_heading' => '<strong>Dienstplan</strong>',
            'rota_body' => 'Die Dienstplanseite ermöglicht es Teamleitern und Managern, Analystenschichten über die Woche zu planen. Legen Sie Standard-Arbeitszeiten fest, weisen Sie Bereitschaftszeiten zu, und markieren Sie Feiertage oder Abwesenheit, damit das Team immer weiß, wer verfügbar ist.',
            'rota_step1' => '<strong>Dienstplanraster ansehen</strong> &mdash; der Dienstplan zeigt Analysten auf einer Achse und Tage auf der anderen, mit Schichtblöcken, die die Abdeckung auf einen Blick zeigen.',
            'rota_step2' => '<strong>Schichten hinzufügen oder bearbeiten</strong> &mdash; klicken Sie auf eine Zelle, um einen Schichttyp zuzuweisen (z. B. Früh, Spät, Nacht, Bereitschaft). Änderungen werden sofort gespeichert.',
            'rota_step3' => '<strong>Vorausplanen</strong> &mdash; navigieren Sie wochenweise vorwärts, um den Dienstplan im Voraus zu erstellen. So stellen Sie eine ausreichende Abdeckung während bekannter Stoßzeiten, Feiertage oder Schulungstage sicher.',
            'rota_step4' => '<strong>Mehrere Zellen auf einmal füllen</strong> &mdash; <strong>rechtsklicken</strong> Sie auf eine Zelle und wählen Sie <em>Kopieren</em>, um die darin enthaltene Schicht aufzunehmen, dann rechtsklicken Sie auf eine andere und <em>Einfügen</em>. Für mehr als eine Zelle <strong>ziehen Sie über einen Block</strong> davon (oder klicken Sie Zellen einzeln mit Strg an) und fügen Sie in alle ein. Das Überfahren einer <strong>Tagesüberschrift</strong> mit der Maus hebt den ganzen Tag hervor, und das Überfahren des <strong>Namens eines Analysten</strong> hebt dessen ganze Woche hervor &mdash; rechtsklicken Sie auf eines von beiden und fügen Sie in alles davon ein. Haben manche der Zellen bereits eine Schicht, bietet das Menü beide Wege in klaren Worten an &mdash; <em>In alle 7 einfügen</em> und <em>In 6 leere Zellen einfügen</em> &mdash;, sodass Sie sich vorher statt nachher entscheiden. Überschreiben fragt zur Bestätigung nach und nennt, wie viele Schichten ersetzt werden; das Füllen von Lücken geschieht einfach, da nichts verloren geht. Dieselben Menüs können auch einen Tag, eine Woche oder eine Auswahl <strong>leeren</strong>, wieder nachdem sie Ihnen gesagt haben, wie viele Schichten das entfernt.',
            'rota_step5' => '<strong>Einen ganzen Tag oder eine ganze Woche für eine Person kopieren</strong> &mdash; rechtsklicken Sie auf eine <strong>Tagesüberschrift</strong> und wählen Sie <em>Kopieren</em>, um jede Schicht an diesem Tag aufzunehmen, oder auf den <strong>Namen eines Analysten</strong>, um dessen ganze Woche aufzunehmen. Das Einfügen auf einen anderen Tag oder einen anderen Analysten gleicht es an: Schichten, die die Kopie nicht hatte, werden geleert, sodass Sie den kopierten Tag erhalten statt einer Mischung aus beiden. Ein Tag kann nur auf einen anderen Tag eingefügt werden und ein Analyst nur auf einen anderen Analysten &mdash; ein Tag ist eine Schicht <em>pro Person</em> und eine Woche eine Schicht <em>pro Tag</em>, es gibt also keine sinnvolle Art, das eine über das andere zu legen. Versuchen Sie es, und das Menü sagt es Ihnen und zeigt, wohin es stattdessen gehen kann.',
            'rota_step6' => '<strong>Eine ganze Woche kopieren</strong> &mdash; <strong>Woche kopieren</strong> und <strong>Woche einfügen</strong> oben rechts nehmen jede Schicht der gerade angezeigten Woche und legen sie auf eine andere - der schnellste Weg, einen sich wiederholenden Dienstplan aufzubauen. Das Einfügen <em>ersetzt</em> die Zielwoche, die Bestätigung nennt also, wie viele Einträge entfernt werden. Es betrifft immer nur die Tage und Personen, die das Raster gerade tatsächlich zeigt.',
            'tip' => 'Kombinieren Sie Kalender und Dienstplan für eine effektive Kapazitätsplanung. Zeigt der Kalender jeden Montagmorgen einen Anstieg der Tickets, stellen Sie sicher, dass der Dienstplan für diesen Zeitraum zusätzliche Abdeckung vorsieht.',
        ],
        'settings' => [
            'heading' => 'Einstellungen',
            'intro' => 'Auf der Einstellungsseite konfigurieren Sie die Bausteine Ihres Ticketsystems. Alle Nachschlagewerte, SLA-Ziele, E-Mail-Integration und benutzerdefinierten Felder werden hier verwaltet.',
            'sla_callout_title' => 'SLA-Verwaltung &mdash; vollständige Anleitung',
            'sla_callout_body' => 'Konfigurierbare Optionen, Geschäftskalender, Pausenstatus, Verletzungsbenachrichtigungen, Einrichtung des Cron-Jobs sowie durchgerechnete Beispiele für Teams in einer und in mehreren Zeitzonen. Umfangreich genug für eine eigene Seite.',
            'card_dept_title' => 'Abteilungen',
            'card_dept_body' => 'Erstellen Sie Abteilungen wie IT, HR und Finanzen. Jede Abteilung wird zu einem Ordner im Posteingang und einem Filter im Dashboard',
            'card_types_title' => 'Tickettypen',
            'card_types_body' => 'Definieren Sie die Arten von Anfragen, die Ihr Desk bearbeitet: Störung, Serviceanfrage, Problem, Änderung. Typen helfen Analysten, Vorgänge zu klassifizieren',
            'card_priorities_title' => 'Prioritäten',
            'card_priorities_body' => 'Legen Sie Prioritätsstufen mit Namen, Farben und Sortierreihenfolgen fest. Jede Priorität ist mit einem SLA-Ziel für Reaktion und Lösung verknüpft',
            'card_statuses_title' => 'Status',
            'card_statuses_body' => 'Passen Sie die Phasen des Ticket-Lebenszyklus an. Die Standardstatus umfassen Neu, Offen, In Bearbeitung, Wartend, Gelöst und Geschlossen',
            'card_categories_title' => 'Kategorien',
            'card_categories_body' => 'Gruppieren Sie Tickets nach technischem Bereich: Hardware, Software, Netzwerk, Zugriff. Kategorien treiben die Auswertungen an',
            'card_sla_title' => 'SLA-Ziele',
            'card_sla_body' => 'Definieren Sie Reaktions- und Lösungszeitziele je Priorität. SLA-Timer erscheinen auf Tickets und lösen Verletzungswarnungen aus',
            'card_email_title' => 'E-Mail-Import',
            'card_email_body' => 'Verbinden Sie ein Postfach (Exchange, Microsoft 365), um E-Mails automatisch als neue Tickets zu importieren. Antworten werden automatisch in bestehende Tickets eingeordnet',
            'card_custom_title' => 'Benutzerdefinierte Felder',
            'card_custom_body' => 'Fügen Sie Tickets eigene Felder für Daten hinzu, die Ihre Organisation erfassen muss und die nicht durch die Standardfelder abgedeckt sind',
            'card_templates_title' => 'E-Mail-Vorlagen',
            'card_templates_body' => 'Konfigurieren Sie die Benachrichtigungsvorlagen, die an Endbenutzer gesendet werden, wenn Tickets erstellt, aktualisiert oder gelöst werden, sowie für die CSAT-Umfrage. Betten Sie Merge-Codes wie [requester_name] und [csat_link] ein',
            'card_checklists_title' => 'Checklisten',
            'card_checklists_body' => 'Legt fest, was passiert, wenn jemand ein Ticket schließt, das noch offene Pflichtschritte einer Checkliste hat: <strong>warnen</strong> und eine interne Notiz erfassen, die die Schritte und die schließende Person nennt, oder den Abschluss <strong>blockieren</strong>, bis sie erledigt sind. Gilt überall, wo ein Ticket geschlossen werden kann - einschließlich Sammelaktionen, REST-API und Workflow-Automatisierung',
            'card_custom_fields_title' => 'Benutzerdefinierte Felder',
            'card_custom_fields_body' => 'Legen Sie die zusätzlichen Angaben fest, die eine Art von Ticket braucht - Text, eine Zahl, ein Datum, Ja / Nein, ein Dropdown mit Ihren eigenen Optionen, eine Web- oder E-Mail-Adresse - und verknüpfen Sie jedes mit einigen Tickettypen oder mit allen. Jedes Feld legt fest, ob es <strong>beim Erfassen des Tickets</strong> (im Formular „Neues Ticket“, in der REST-API und, falls gewünscht, im Portal), <strong>vor dem Schließen</strong> (gemäß der Regel für Pflichtfelder) oder in beiden Fällen ausgefüllt sein muss, und ob der <strong>Anfragende danach gefragt wird</strong> im Portal - wo eine Auswahl des Tickettyps erscheint, sobald sie ändert, was gefragt wird. Antworten werden im Eigenschaftenbereich des Tickets und in seinem Verlauf angezeigt. Wenn Sie den Typ eines Tickets ändern, werden die Antworten ausgeblendet, die der neue Typ nicht hat, aber nie gelöscht',
            'card_mandatory_title' => 'Pflichtfelder',
            'card_mandatory_body' => 'Haken Sie die Felder an, die vor dem Schließen eines Tickets ausgefüllt sein müssen - Kategorie, Lösungscode, Eigentümer und so weiter. Wählen Sie dann, was passiert, wenn jemand eines mit leerem Feld schließt: <strong>warnen</strong>, <strong>warnen und per E-Mail benachrichtigen</strong>, zum Beispiel einen Service Delivery Manager, oder das Schließen <strong>verweigern</strong>. Ein separater Schalter erfasst es am Ticket als interne Notiz. Ein für ein Unternehmen ausgeschaltetes Feld ist nie erforderlich, und das Zusammenführen von Tickets löst es nie aus. Wird überall durchgesetzt, wo ein Ticket geschlossen werden kann - einschließlich Sammelaktionen, REST-API und Workflow-Automatisierung',
            'card_cleanup_title' => 'Antwort-Bereinigung KI',
            'card_cleanup_body' => 'Anthropic-Schlüssel + Modell + Ton für die Schaltfläche ✨ Bereinigen im Antwort-Editor. Eigener Schlüssel getrennt von anderen KI-Funktionen für eine granulare Abrechnung',
            'card_csat_title' => 'CSAT',
            'card_csat_body' => 'Sendemodus (aus / automatisch / manuell), Verzögerung, Schutz vor Mehrfachversand pro Ticket, Skala (Sterne oder Emojis). Siehe Abschnitt 6 für den vollständigen Ablauf',
            'email_heading' => '<strong>E-Mail-Import im Detail</strong>',
            'email_body' => 'Die E-Mail-Importfunktion verbindet sich mit Ihrem gemeinsamen Postfach und übernimmt neue Nachrichten als Tickets. Sendet ein Endbenutzer eine E-Mail an Ihre Support-Adresse (z. B. support@ihrunternehmen.de), erstellt FreeITSM ein Ticket mit dem E-Mail-Betreff als Titel und dem E-Mail-Text als Beschreibung. Antwortet der Absender auf eine Benachrichtigungs-E-Mail, wird die Antwort in das bestehende Ticket eingeordnet, statt ein Duplikat zu erstellen.',
            'email_step1' => '<strong>Postfach konfigurieren</strong> &mdash; gehen Sie zu Einstellungen und geben Sie Ihre Exchange- oder Microsoft-365-Zugangsdaten ein. OAuth-Authentifizierung wird für sichere, passwortlose Verbindungen unterstützt.',
            'email_step2' => '<strong>Abfrageintervall festlegen</strong> &mdash; wählen Sie, wie häufig FreeITSM das Postfach auf neue Nachrichten prüft. Kürzere Intervalle bedeuten schnellere Ticketerstellung.',
            'email_step3' => '<strong>Standardwerte zuordnen</strong> &mdash; legen Sie die Standardabteilung, den Standardtyp und die Standardpriorität für aus E-Mail erstellte Tickets fest. Analysten können diese nach dem Import anpassen.',
            'tip' => 'Nutzen Sie E-Mail-Vorlagen, um einen professionellen, einheitlichen Ton in der gesamten Kommunikation mit Endbenutzern zu wahren. Vorlagen unterstützen dynamische Platzhalter für Ticketreferenz, Name des Anfragenden, Name des Analysten und Status.',
            'closemsg_heading' => '<strong>Eine einmalige Nachricht beim Schließen eines Tickets</strong>',
            'closemsg_body' => 'Setzen Sie <code>[ticket_closed_message]</code> irgendwo in eine aktive Vorlage <strong>Ticket geschlossen</strong>, und von da an fragt das Setzen eines Tickets auf einen geschlossenen Status den Analysten nach einem Satz - <em>„das Ersatzladegerät liegt auf Ihrem Schreibtisch“</em>, <em>„wie am Telefon vereinbart geschlossen“</em>. Was er eingibt, landet genau dort, wo Sie den Platzhalter gesetzt haben, sodass Sie die Kontrolle über den Wortlaut drumherum behalten. Es ist keine Einstellung, und nichts speichert es: eine Notiz, ein Ticket, eine E-Mail. Geben Sie nichts ein, ist die Zeile einfach nicht da - keine Lücke, kein überflüssiges Satzzeichen.',
            'closemsg_note' => '<strong>Die Aufforderung erscheint nur, wenn der Platzhalter tatsächlich in der Vorlage steht.</strong> Ohne ihn würde alles, was ein Analyst eingegeben hat, stillschweigend verworfen, und jedes Team, das dies nicht möchte, bekäme einen zusätzlichen Klick bei jedem einzelnen Schließen. Es schaltet sich also selbst ein, wenn Sie es konfigurieren, und bleibt außer dem Weg, wenn Sie es nicht getan haben.',
            'cat_heading' => '<strong>Kategorien und die beiden Felder daneben</strong>',
            'cat_body' => 'Ein Ticket-<em>Typ</em> sagt, um welche Art von Sache es sich handelt; eine <em>Kategorie</em> sagt, worum es geht. Erstellen Sie die Liste unter <strong>Einstellungen &rarr; Kategorien</strong>, zusammen mit den Schaltern, die entscheiden, ob davon überhaupt etwas auf einem Ticket erscheint.',
            'cat_card_one_title' => 'Kategorie',
            'cat_card_one_body' => 'Als was das Ticket gemeldet wurde, gewählt bei der Erstellung. Ein Ticket trägt genau eine, sodass eine Auswertung Ihrer Kategorien immer der Anzahl der tatsächlich vorhandenen Tickets entspricht.',
            'cat_card_close_title' => 'Abschlusskategorie',
            'cat_card_close_body' => 'Dieselbe Liste, erneut abgefragt, wenn das Ticket abgeschlossen wird. Meist bestätigt der Analyst nur den ersten Wert &mdash; ihren Nutzen zeigt sie bei den Tickets, wo die erste Vermutung falsch war, und so erfahren Sie, dass zwölf Ihrer siebenunddreißig „Druckerprobleme“ in Wirklichkeit das Netzwerk waren.',
            'cat_card_res_title' => 'Lösungscode',
            'cat_card_res_body' => 'Wie das Ticket endete, statt worum es ging &mdash; „Remote behoben“, „Schulung durchgeführt“, „Kein Fehler gefunden“. Zehn sinnvolle sind von Anfang an vorhanden, und Sie können sie alle ändern.',
            'cat_rule_off' => '<strong>Alle drei sind zunächst ausgeschaltet.</strong> Erstellen Sie zuerst Ihre Liste und schalten Sie dann die gewünschten ein. Jede lässt sich für jedes Unternehmen unterschiedlich einstellen.',
            'cat_rule_levels' => 'Kategorien können bis zu drei Ebenen tief Unterkategorien haben, keine Ebene ist Pflicht.',
            'cat_rule_type' => 'Eine Kategorie kann an einen Tickettyp gebunden werden, sodass „Onboarding neuer Benutzer“ nur bei einer Serviceanfrage angeboten wird. Die Bindung gehört zur Kategorie oberster Ebene, ihre Unterkategorien folgen ihr.',
            'cat_rule_typechange' => '<strong>Das Ändern des Tickettyps entfernt eine Kategorie, die zum alten Typ gehörte</strong>, und meldet dies auf dem Bildschirm. Eine Kategorie, die an keinen Typ gebunden ist, übersteht die Änderung.',
            'cat_rule_portal' => 'Aktivieren Sie <em>Kunden können dies auswählen</em>, um eine Kategorie im Self-Service-Portal anzubieten. Anfragende sehen eine kurze, klar formulierte Liste, während Analysten den ganzen Baum sehen.',
            'cat_rule_retire' => 'Schalten Sie eine Kategorie aus, um sie außer Betrieb zu nehmen &mdash; sie bleibt auf Tickets erhalten, die sie bereits haben, wird aber bei neuen nicht mehr angeboten. Das ist fast immer besser als Löschen, was verweigert wird, solange noch etwas sie verwendet.',
            'cat_rule_report' => 'Alle drei lassen sich im Ticket-Dashboard als Diagramm darstellen. Die beiden Kategorie-Diagramme fassen bis zur obersten Ebene zusammen, und Tickets ohne Angabe werden als <em>Nicht kategorisiert</em> gezählt statt ausgeblendet.',
            'cat_tip' => 'Wenn Sie nicht wissen, wo Sie anfangen sollen, lassen Sie die Kategorien leer und schalten Sie allein <strong>Lösungscode</strong> ein. Das ist das Feld, das am schnellsten etwas an Ihrem Handeln ändert &mdash; wenn ein Fünftel Ihrer Tickets als „Schulung durchgeführt“ zurückkommt, ist das ein Dokumentationsproblem, kein IT-Problem.',
        ],
        'tips' => [
            'heading' => 'Kurztipps',
            'search_title' => 'Alles durchsuchen',
            'search_body' => 'Das Suchdialogfeld prüft Ticketreferenzen, Betreffzeilen, Namen der Anfragenden und E-Mail-Adressen. Nutzen Sie es, um verwandte Tickets schnell zu finden, wenn ein Benutzer wegen eines bestehenden Problems anruft.',
            'sla_title' => 'Behalten Sie Ihre SLAs im Blick',
            'sla_body' => 'SLA-Timer sind bei jedem Ticket im Lesefenster sichtbar. Farblich codierte Anzeigen werden gelb, wenn eine Verletzung bevorsteht, und rot, wenn das Ziel verfehlt wurde, sodass Sie entsprechend priorisieren können.',
            'reply_title' => 'Aus dem Posteingang antworten',
            'reply_body' => 'Sie müssen Ihren E-Mail-Client nicht öffnen, um einem Endbenutzer zu antworten. Nutzen Sie die Schaltfläche Antworten im Lesefenster, um direkt eine Nachricht zu senden. Sie wird automatisch in das Ticket eingeordnet.',
            'trail_title' => 'Das Aktivitätsprotokoll nutzen',
            'trail_body' => 'Bevor Sie an einem Ticket arbeiten, scrollen Sie durch das Aktivitätsprotokoll. Frühere Analystennotizen, E-Mails und Feldänderungen geben Ihnen den vollständigen Kontext, damit Sie den Benutzer nicht bitten müssen, Informationen zu wiederholen.',
            'dash_title' => 'Dashboard für Manager',
            'dash_body' => 'Erstellen Sie ein Dashboard mit Widgets für SLA-Einhaltungsraten, durchschnittliche Lösungszeit und Tickets nach Abteilung. Teilen Sie es in Teambesprechungen, um kontinuierliche Verbesserung voranzutreiben.',
            'rota_title' => 'Mit dem Dienstplan planen',
            'rota_body' => 'Füllen Sie den Dienstplan mindestens zwei Wochen im Voraus aus. In Kombination mit der Kalenderansicht hilft er Ihnen, Lücken in der Abdeckung zu erkennen, bevor sie zu einem Problem für die Reaktionszeiten werden.',
            'drag_title' => 'Per Ziehen bewerten',
            'drag_body' => 'Ziehen Sie Tickets aus der Liste auf Ordner, um sie zu aktualisieren, ohne sie zu öffnen. Abteilungs- und Status-Unterordner aktualisieren beides gleichzeitig. Selbstöffnende Ordner machen verschachtelte Status während des Ziehens erreichbar.',
            'dbl_title' => 'Doppelklick für Vollbild',
            'dbl_body' => 'Ein Klick zeigt eine Vorschau des Tickets im Lesefenster; ein Doppelklick öffnet es im Vollbildmodus für konzentriertes Arbeiten. Klicken Sie auf das Maximieren-Symbol neben dem Betreff, um zurückzuschalten.',
            'rightclick_title' => 'Rechtsklick für Schnellaktionen',
            'rightclick_body' => 'Rechtsklicken Sie ein Ticket für Status-, Prioritäts- oder Bearbeiteränderungen per Klick sowie CMDB-Verknüpfung und Zeiterfassung, ohne das gerade gelesene Ticket zu verlassen.',
            'ai_title' => 'KI beim Bereinigen Ihrer Antwort nutzen',
            'ai_body' => 'Tippen Sie einen groben Entwurf (oder nur Stichpunkte) und klicken Sie auf <strong>✨ Bereinigen</strong> &mdash; Claude formt ihn in eine ordentliche E-Mail mit Anrede, Grammatikkorrektur und Grußformel um. Der Rückgängig-Link erscheint für 30 Sekunden.',
            'feedback_title' => 'Um Rückmeldung bitten',
            'feedback_body' => 'Schalten Sie CSAT unter <strong>Einstellungen &rarr; CSAT</strong> ein, um Anfragende automatisch zu befragen, wenn ihre Tickets geschlossen werden. Trends pro Analyst finden Sie unter <code>tickets/csat/</code> &mdash; wertvoll für Entwicklungsgespräche.',
            'precreate_title' => 'Endbenutzer im Voraus anlegen',
            'precreate_body' => 'Mit der Navigationsschaltfläche <strong>Benutzer</strong> können Sie einen Benutzer anlegen, bevor er ein Ticket erstellen muss &mdash; lassen Sie das Passwort leer, und er kann das Konto selbst über das Self-Service-Portal übernehmen.',
        ],
        'companies' => [
            'heading' => 'Unternehmen &amp; E-Mail-Routing',
            'intro' => 'Bedient Ihre Installation mehr als ein Unternehmen (zum Beispiel ein IT-Dienstleister, der mehrere Kunden betreut), werden die Tickets jedes Unternehmens getrennt gehalten. Dieser Abschnitt erklärt, wie eingehende E-Mails das richtige Unternehmen finden.',
            'switcher_body' => 'Ein <strong>Unternehmensschalter</strong> erscheint im Kopfbereich. Er legt fest, in welchem Unternehmen Sie arbeiten &mdash; die Ticketliste, Ordner und Zähler zeigen nur dieses Unternehmen an, und jedes von Ihnen erstellte Ticket wird dort abgelegt. Mitarbeiter mit Zugriff auf mehrere Unternehmen können zwischen ihnen wechseln; das aktuelle wird stets angezeigt, damit Sie nie im falschen Kontext antworten. Verwalten Sie die Unternehmen selbst unter <strong>System &rarr; Unternehmen</strong>.',
            'mailboxes_heading' => 'Jedes Postfach ist eine von zwei Arten &mdash; das entscheidet über das Routing:',
            'card_pinned_title' => 'Festgelegtes Postfach',
            'card_pinned_body' => 'Einem Unternehmen fest zugeordnet (z. B. das eigene <code>itsupport@</code> eines Kunden). <strong>Die gesamte</strong> Post wird diesem Unternehmen zugeordnet &mdash; der Absender wird ignoriert &mdash; und Antworten gehen von dort aus zurück, sodass der Kunde durchgehend seinen eigenen Helpdesk sieht.',
            'card_shared_title' => 'Gemeinsames Eingangspostfach',
            'card_shared_body' => 'Eine Adresse, die viele Unternehmen bedient (z. B. das einzige <code>support@derdienstleister.com</code> eines Anbieters). Sie kann das Unternehmen nicht allein aus der Adresse erkennen und ermittelt es daher aus <strong>dem Absender der E-Mail</strong>. Die empfohlene Einrichtung für einen Dienstleister mit vielen Kunden.',
            'routing_heading' => 'Wie ein gemeinsames Eingangspostfach das Unternehmen ermittelt',
            'routing_body' => 'Bei jeder eingehenden E-Mail wird der Reihe nach geprüft, und der erste Treffer gewinnt:',
            'flow_reply' => 'Antwort auf ein Ticket',
            'flow_sender' => 'Bekannter Absender',
            'flow_domain' => 'Bekannte Domäne',
            'flow_triage' => 'Triage',
            'rule_reply' => '<strong>1. Antwort auf ein bestehendes Ticket</strong> &mdash; anhand der Referenz erkannt, wird die E-Mail diesem Ticket zugeordnet und behält dessen Unternehmen.',
            'rule_sender' => '<strong>2. Eine bestimmte Absenderadresse</strong>, die einem Unternehmen zugeordnet ist (z. B. <code>jane@gmail.com</code> &rarr; Acme) &mdash; dieses Unternehmen. Wird vor der Domäne geprüft und funktioniert daher auch für persönliche/Webmail-Adressen.',
            'rule_domain' => '<strong>3. Die Domäne des Absenders</strong>, die einem Unternehmen zugeordnet ist (z. B. jeder unter <code>@acme.com</code> &rarr; Acme) &mdash; dieses Unternehmen.',
            'rule_triage' => '<strong>4. Kein Treffer</strong> &mdash; die E-Mail geht in die <strong>Triage</strong>-Warteschlange, statt verloren zu gehen (siehe unten).',
            'keys_heading' => 'Domänen &amp; bestimmte Absender (pro Unternehmen festgelegt unter System &rarr; Unternehmen)',
            'keys_body' => 'Dies sind die Schlüssel, nach denen ein gemeinsames Eingangspostfach abgleicht. Jedes Unternehmen listet die ihm gehörenden E-Mail-Domänen und optional einzelne Absenderadressen.',
            'card_domains_title' => 'E-Mail-Domänen',
            'card_domains_body' => 'Die einem Unternehmen gehörenden Domänen (acme.com, acme.co.uk). Jeder Absender auf einer registrierten Domäne wird diesem Unternehmen zugeordnet. Eine Domäne gehört nur einem Unternehmen.',
            'card_senders_title' => 'Bestimmte Absender',
            'card_senders_body' => 'Einzelne, einem Unternehmen zugeordnete Adressen, vor der Domäne geprüft. Nutzen Sie dies für einen Freiberufler oder kleinen Kunden, der von einer persönlichen Adresse aus schreibt.',
            'card_public_title' => 'Öffentliche Anbieter',
            'card_public_body' => 'Gmail, Outlook, Yahoo und Ähnliches lassen sich nicht als Domäne zuordnen (viele voneinander unabhängige Personen teilen sie) &mdash; ordnen Sie stattdessen die genaue Adresse als bestimmten Absender zu.',
            'triage_heading' => 'Die Triage-Warteschlange &mdash; das Sicherheitsnetz',
            'triage_body' => 'Passt eine E-Mail aus einem gemeinsamen Eingangspostfach zu keinem Unternehmen, landet sie in der <strong>Triage</strong> (erreichbar über den Unternehmensschalter, mit Live-Zähler), statt verloren zu gehen. Jeder Eintrag zeigt Absender, Domäne, Betreff und das Postfach, an dem er ankam. Ordnen Sie ihn in einem Schritt einem Unternehmen zu:',
            'triage_create' => 'Wählen Sie ein bestehendes Unternehmen, oder legen Sie direkt ein neues an.',
            'triage_assign' => 'Bei einer normalen Domäne können Sie optional <strong>diese Domäne dem Unternehmen zuordnen</strong>; bei einer öffentlichen/Webmail-Adresse können Sie optional <strong>diesen Absender immer dorthin zuordnen</strong>.',
            'triage_sweep' => 'Beide Optionen <em>fegen mit</em>: Sie verschieben auch jede andere wartende E-Mail dieser Domäne oder Adresse und ordnen künftige Post automatisch zu &mdash; sodass Sie einen Absender nur einmal einordnen müssen.',
            'triage_tip' => 'Es geht nie etwas verloren. Nicht zugeordnete Post wartet in der Triage, bis jemand sie einordnet; ein nicht eingeordnetes Ticket erscheint in der Zwischenzeit weiterhin unter dem Standardunternehmen.',
            'test_heading' => 'Testen Sie Ihr Routing vor dem Live-Betrieb',
            'test_body' => 'Unter <strong>System &rarr; E-Mail-Routing-Test</strong> können Sie den Eingang einer E-Mail simulieren &mdash; wählen Sie ein Postfach, geben Sie eine Absenderadresse ein &mdash; und sehen genau, in welchem Unternehmen das neue Ticket landen würde (oder dass es in die Triage ginge) und welche Regel entschieden hat. Es wird nichts angelegt; es liest nur Ihre Einstellungen.',
            'settings_heading' => 'Einstellungen: standardmäßig gemeinsam, angepasst wo es zählt',
            'settings_body' => 'Manche dieser Einstellungen lassen sich <strong>pro Unternehmen anpassen</strong>; andere bleiben absichtlich gemeinsam. Handelt es sich um eine einfache Liste von Optionen &mdash; wie <strong>Tickettypen</strong> und <strong>Quellen</strong> &mdash; sehen Sie beim Wechsel in den Kontext eines Unternehmens die gemeinsamen Standardwerte (jeweils mit einem Augen-Symbol, um nicht genutzte auszublenden) sowie alle, die es speziell für sich selbst hinzugefügt hat. Sie können eine Option nicht ausblenden oder löschen, solange offene Tickets sie noch verwenden, und die gemeinsamen Standardwerte selbst werden vom MSP- bzw. Standardunternehmen aus bearbeitet.',
            'settings_custom_title' => 'Pro Unternehmen angepasst',
            'settings_custom_body' => 'Tickettypen &amp; Quellen (jetzt) sowie Kategorien, SLAs &amp; Geschäftszeiten (demnächst) &mdash; Dinge, die sich von einem Kunden zum nächsten tatsächlich unterscheiden.',
            'settings_global_title' => 'Für alle Unternehmen gemeinsam',
            'settings_global_body' => 'Status und Prioritäten bleiben überall gleich, damit unternehmensübergreifende Auswertungen und SLAs konsistent bleiben; ebenso Ihre Teams, der Dienstplan und die Postfächer &mdash; Ihr eigener Betrieb, nicht der eines Kunden.',
            'allview_heading' => '<strong>Ein Board über alle Unternehmen hinweg</strong>',
            'allview_body' => 'Der Unternehmens-Umschalter in der Kopfzeile hat eine Option <strong>Alle Unternehmen</strong>. Jedes Ticket, das Sie sehen dürfen, erscheint in einer Liste, wobei jede Zeile das Unternehmen zeigt, zu dem sie gehört &mdash; nützlich, wenn Sie mehrere Einheiten betreuen und einen einzigen Überblick über den Tag wollen, ohne den Überblick zu verlieren, wem was gehört.',
            'allview_card_scope_title' => 'Es gewährt nichts Neues',
            'allview_card_scope_body' => '„Alle“ bedeutet jedes Unternehmen, das Sie ohnehin schon einzeln erreichen konnten. Ein Analyst, der zwei Ihrer drei Einheiten betreut, sieht genau diese zwei, und ein Analyst mit einem Unternehmen sieht eine Ansicht dieses einen Unternehmens.',
            'allview_card_props_title' => 'Jede Einheit bleibt getrennt',
            'allview_card_props_body' => 'Öffnen Sie ein Ticket, gehören sein Typ, seine Herkunft, seine Kategorie- und Lösungsliste zu <em>diesem</em> Unternehmen &mdash; sodass eine Kategorie, die eine Einheit hat und eine andere nicht, nie auf das falsche Ticket angewendet werden kann.',
            'allview_card_new_title' => 'Neue Tickets fragen nach dem Unternehmen',
            'allview_card_new_body' => 'Es gibt kein einzelnes aktives Unternehmen, das angenommen werden könnte, und die Wahl entscheidet über die Ticketnummer, das Postfach, aus dem Antworten gesendet werden, und die geltende SLA. Die Typenliste füllt sich, sobald Sie gewählt haben.',
            'allview_rule_chip' => 'Ein Ticket, das per E-Mail oder Portal eingegangen ist, ohne bereits zugeordnet zu sein, wird als <strong>Nicht zugeordnet</strong> markiert statt unter Standard angezeigt, damit es für die Triage auffällt.',
            'allview_rule_reply' => 'Antworten gehen weiterhin von dem Postfach aus, bei dem das Ticket eingegangen ist &mdash; das folgt dem Ticket, nicht der Ansicht, sodass ein kombiniertes Board nie von der falschen Adresse senden kann.',
            'allview_rule_knowledge' => '<strong>KI fragen</strong> durchsucht bei aktivierter kombinierter Ansicht alle Unternehmen, die Sie sehen können, statt nur eines. Mit allen Unternehmen geteilte Artikel sind in jedem Fall enthalten.',
            'allview_rule_trash' => '<strong>Das Leeren des Papierkorbs erstreckt sich nie über mehrere Unternehmen.</strong> Es betrifft immer nur das eine Unternehmen, das Sie zuletzt gewählt haben, denn „alles im Papierkorb löschen“ über mehrere Einheiten hinweg gleichzeitig meint niemand wirklich so.',
            'allview_rule_other' => 'Nur die Ticketliste wird erweitert. Assets, Changes, Aufgaben und die CMDB zeigen weiterhin jeweils ein Unternehmen &mdash; wechseln Sie zu diesem Unternehmen, um darin zu arbeiten.',
            'privacy_heading' => 'Die Tickets jedes Unternehmens bleiben privat',
            'privacy_body' => 'Wenn Sie im Kontext eines Unternehmens arbeiten, sehen Sie ausschließlich die Tickets <strong>dieses</strong> Unternehmens &mdash; in der Liste, in der Suche, in Dashboards und bei jedem geöffneten Ticket (einschließlich E-Mails, Anhänge, Notizen und Verlauf). Ein Mitarbeiter erreicht ein Ticket nur, wenn ihm Zugriff auf dessen Unternehmen gewährt wurde (Sie legen die Unternehmen jedes Analysten unter System &rarr; Analysten fest oder gewähren ihn einem ganzen Team unter System &rarr; Teams), sodass es keine Möglichkeit gibt, versehentlich in die Daten eines anderen Kunden zu geraten. Diese Trennung wird überall im Hintergrund durchgesetzt, nicht nur in der Ansicht verborgen. Bei einer Installation mit nur einem Unternehmen geschieht dies automatisch und unsichtbar &mdash; es gibt nur ein Unternehmen, dem einfach alles gehört.',
            'tip' => 'Bei einer Installation mit nur einem Unternehmen erscheint nichts davon &mdash; es gibt ein Unternehmen, jedes Ticket gehört dazu, und es gibt keinen Schalter oder Triage. Diese Funktionen schalten sich erst ein, sobald ein zweites Unternehmen existiert.',
        ],
    ],
    'help_sla' => [
        'page_title' => 'SLA-Verwaltung',
        'back_link' => '&larr; Zurück zum Ticket-Leitfaden',
        'sidebar_title' => 'SLA-Leitfaden',
        'hero_title' => 'SLA-Verwaltung',
        'hero_sub' => 'Reaktions- und Lösungsziele, die Geschäftszeiten berücksichtigen, mit Verletzungsmeldungen je Abteilung',
        'nav' => [
            'overview' => 'Überblick',
            'building_blocks' => 'Bausteine',
            'behaviour_settings' => 'Verhaltenseinstellungen',
            'breach_notifications' => 'Verletzungsmeldungen',
            'cron_setup' => 'Cron-Job einrichten',
            'worked_examples' => 'Durchgerechnete Beispiele',
            'troubleshooting' => 'Fehlersuche',
        ],
        'overview' => [
            'heading' => 'Überblick',
            'sub' => 'Was SLAs sind, warum sie wichtig sind und wie die FreeITSM-Engine im Groben arbeitet.',
            'p1' => 'Ein Service Level Agreement (SLA) ist eine Zusage darüber, wie schnell Ihr Team auf ein Ticket reagiert und es löst. FreeITSM führt je Ticket zwei Uhren: <strong>Reaktion</strong> (Zeit von der Erstellung bis zur ersten Handlung eines Analysten) und <strong>Lösung</strong> (Zeit von der Erstellung bis zum Schließen). Beide Ziele werden je Priorität festgelegt — eine P1 kann also 30 Minuten für die Reaktion und 4 Stunden für die Lösung haben, eine P4 dagegen 8 Arbeitsstunden und 5 Arbeitstage.',
            'switch_note' => 'Sie verwenden keine SLAs? Schalten Sie SLA unter <strong>System &rarr; Module &rarr; Verfügbarkeit &rarr; Ticketfunktionen</strong> aus: Zeitzähler, Verletzungswarnungen und SLA-Workflow-Auslöser stoppen, während die Geschäftskalender für die Öffnungszeiten des Web-Chats erhalten bleiben. Beim Wiedereinschalten werden Sie gefragt, ob die in der Zwischenzeit verpassten Warnungen gesendet oder übersprungen werden sollen.',
            'p2' => 'Die SLA-Engine von FreeITSM beruht auf vier Entwurfsentscheidungen, die man kennen sollte:',
            'choice_business' => '<strong>Geschäftszeiten, nicht Wanduhr.</strong> Eine um 16:30 Uhr erstellte P2 mit einem Reaktionsziel von 1 Stunde verletzt das Ziel nicht um 17:30 Uhr, wenn das Büro um 17:00 Uhr schließt. Die Uhr läuft am nächsten Arbeitstag um 9:00 Uhr weiter. Das ist Branchenstandard und das einzig faire Modell, wenn Analysten abends nach Hause gehen.',
            'choice_pause' => '<strong>Anhaltbar.</strong> Befindet sich ein Ticket in einem Status mit dem Kennzeichen „SLA anhalten“ (etwa <em>Wartet auf Rückmeldung</em> oder <em>Zurückgestellt</em>), steht die Uhr still. Sie läuft weiter, sobald das Ticket in einen Arbeitsstatus zurückkehrt.',
            'choice_compute' => '<strong>Beim Lesen berechnet, nicht gespeichert.</strong> Die Engine berechnet den SLA-Zustand bei jeder Ansicht neu aus dem Ticketverlauf. Es gibt keine gespeicherten Zähler, die auseinanderlaufen könnten. Ändern Sie später die Zeiten eines Geschäftskalenders, wird die SLA jedes historischen Tickets beim nächsten Aufruf gegen die neuen Zeiten neu berechnet.',
            'choice_cutoff' => '<strong>Stichtag der Durchsetzung.</strong> Ein vom Administrator gesetztes Datum „SLAs durchsetzen ab“ sorgt dafür, dass bestehende Tickets beim Einschalten der SLAs nicht plötzlich rückwirkend als verletzt gelten. Erfasst werden nur Tickets, die am Stichtag oder danach erstellt wurden.',
            'tip' => 'Falls Sie neu bei ITIL sind: Bei der Reaktionszeit geht es um die Bestätigung (jemand hat sich der Sache angenommen), bei der Lösungszeit um den Abschluss (das Problem des Benutzers ist behoben). Die beiden Uhren laufen unabhängig voneinander und haben unterschiedliche Ziele.',
        ],
        'blocks' => [
            'heading' => 'Die vier Bausteine',
            'sub' => 'Richten Sie diese vier Dinge ein, und die SLA-Erfassung läuft. Alles andere ist freiwillige Feinabstimmung.',
            'cal_heading' => '1. Geschäftskalender',
            'cal_intro' => 'Ein Kalender legt fest, wann Ihr Service Desk geöffnet ist. Jeder Kalender hat:',
            'cal_tz' => '<strong>Zeitzone</strong> &mdash; eine IANA-Zeitzonenkennung (z. B. <code>Europe/Berlin</code>, <code>America/New_York</code>, <code>Asia/Singapore</code>). Die Umstellung auf Sommer- und Winterzeit wird automatisch berücksichtigt.',
            'cal_hours' => '<strong>Wöchentliche Arbeitszeiten</strong> &mdash; eine Zeile je Wochentag mit einem Kontrollkästchen „Geöffnet“ sowie Anfangs- und Endzeit. Neue Kalender starten mit Mo–Fr 09:00–17:00 Uhr, Sa/So geschlossen. Eine Zeile ohne Häkchen bedeutet, dass der Desk an diesem Tag geschlossen ist.',
            'cal_holidays' => '<strong>Feiertage</strong> &mdash; Datum und optionaler Name. Feiertage überschreiben das Wochenmuster (der Desk ist geschlossen, auch wenn der Tag auf einen Montag fällt).',
            'cal_default' => '<strong>Standardkennzeichen</strong> &mdash; genau ein Kalender ist der Standard. Neue Prioritäten übernehmen ihn, sofern Sie nichts anderes angeben.',
            'cal_outro' => 'Sie können beliebig viele Kalender anlegen — einen je Standort, einen je Team, einen für VIP-Kunden mit erweiterten Zeiten. Sie werden von den SLA-Zielen und der Verletzungsprüfung gemeinsam genutzt.',
            'prio_heading' => '2. Prioritäten mit SLA-Zielen',
            'prio_intro' => 'Im Reiter „Prioritäten“ (oder über die Tabelle der SLA-Ziele im Reiter „SLA“) kann jede Priorität Folgendes haben:',
            'prio_response' => '<strong>Reaktionsziel (Minuten)</strong> &mdash; wie lange bis zur ersten Handlung eines Analysten.',
            'prio_resolution' => '<strong>Lösungsziel (Minuten)</strong> &mdash; wie lange, bis das Ticket geschlossen ist.',
            'prio_calendar' => '<strong>Kalender</strong> &mdash; gegen welchen Geschäftskalender die Uhr dieser Priorität läuft. Leer lassen, um den Standardkalender zu verwenden.',
            'prio_outro' => 'Lässt man beide Zielfelder leer, wird die SLA-Erfassung für diese Priorität vollständig abgeschaltet — nützlich für eine Priorität „Zur Information“ oder „Backlog“, bei der kein Zeitdruck besteht.',
            'pause_heading' => '3. Status, die die SLA anhalten',
            'pause_intro' => 'Im Reiter „Status“ gibt es eine eigene Spalte „SLA anhalten“. Kennzeichnen Sie damit jeden Status, der bedeutet, dass das Ticket auf etwas außerhalb des Einflussbereichs des Teams wartet. Übliche Kandidaten sind:',
            'pause_awaiting' => '<strong>Wartet auf Rückmeldung</strong> &mdash; der Kunde schuldet uns Informationen. Fast überall als faire Unterbrechung anerkannt.',
            'pause_vendor' => '<strong>Zurückgestellt (Hersteller)</strong> &mdash; wartet auf Microsoft oder einen Drittanbieter-Support.',
            'pause_change' => '<strong>Zurückgestellt (Wartungsfenster)</strong> &mdash; für ein künftiges Wartungsfenster eingeplant.',
            'pause_parts' => '<strong>Zurückgestellt (Ersatzteile)</strong> &mdash; wartet auf eine Hardwarelieferung.',
            'pause_warn' => 'Ein allgemeiner Status „Zurückgestellt“ lässt sich als Notausgang aus der SLA missbrauchen, wenn ein Ticket schwierig oder der Analyst ausgelastet ist. Hat Ihr Team die nötige Disziplin, ist das kein Problem. Andernfalls ersetzen Sie ihn besser durch die genaueren Varianten oben — oder verlassen Sie sich auf das <strong>Wachtturm</strong>-Dashboard, das über 24 Stunden angehaltene Tickets als gelbe Warnung ausweist.',
            'cutoff_heading' => '4. Stichtag der Durchsetzung (<code>SLAs durchsetzen ab</code>)',
            'cutoff_p1' => 'Die mit Abstand wichtigste globale Einstellung. Solange hier kein Zeitpunkt steht, ist die SLA-Erfassung vollständig abgeschaltet — es laufen keine Uhren, im Posteingang erscheinen keine Kennzeichen, und es werden keine Verletzungsmeldungen versendet. Ein Zeitpunkt in der Vergangenheit schaltet SLAs rückwirkend ab diesem Moment ein; ein Zeitpunkt in der Zukunft plant die Einschaltung.',
            'cutoff_p2' => 'Die meisten Teams setzen ihn beim ersten Aktivieren auf „jetzt“ — bestehende Tickets behalten ihren Zustand vor der SLA, neue Tickets ab diesem Moment werden erfasst.',
        ],
        'behaviour' => [
            'heading' => 'Verhaltenseinstellungen',
            'sub' => 'Diese steuern, wie die Engine auf Sonderfälle reagiert. Die Vorgaben sind sinnvoll — Sie müssen sie nur anfassen, wenn Sie es ausdrücklich anders möchten.',
            'prio_heading' => 'Wenn sich die Priorität mitten im Lauf ändert',
            'prio_intro' => 'Wird ein P3-Ticket auf halber Strecke zu einer P1 hochgestuft (weil sich die Sache als größer herausstellt), gibt es drei vertretbare Verhaltensweisen:',
            'prio_forward' => '<strong>Übertragen (Standard)</strong> &mdash; die bereits verbrauchten Geschäftsminuten bleiben erhalten, nur das Ziel wird neu gesetzt. Hatte das Ticket 2 Stunden seines 8-Stunden-P3-Ziels verbraucht, stehen diese 2 Stunden nun gegen das 1-Stunden-P1-Ziel — es ist also bereits verletzt. Durchaus richtig so: Die Sache WAR die ganze Zeit eine P1, das Team hat es nur nicht bemerkt.',
            'prio_recompute' => '<strong>Neu berechnen</strong> &mdash; die Uhr zurücksetzen und das neue Ziel rückwirkend ab Ticketerstellung anwenden. Eine saubere Neuberechnung.',
            'prio_reset' => '<strong>Zurücksetzen</strong> &mdash; die neue Uhr ab dem Moment der Prioritätsänderung frisch starten. Am nachsichtigsten gegenüber dem Team, aber Kunden könnten sich getäuscht fühlen, wenn ein hochpriorisiertes Ticket plötzlich eine neue, lange Frist bekommt.',
            'reopen_heading' => 'Wenn ein geschlossenes Ticket wieder geöffnet wird',
            'reopen_intro' => 'Wird ein Ticket wieder geöffnet (der Benutzer antwortet nach dem Schließen):',
            'reopen_reset' => '<strong>Zurücksetzen (Standard)</strong> &mdash; eine frische Reaktions- und Lösungsuhr ab dem Moment der Wiedereröffnung. Die Wiedereröffnung gilt praktisch als neues Ticket.',
            'reopen_continue' => '<strong>Fortsetzen</strong> &mdash; ab der beim Schließen verstrichenen Zeit weiterlaufen. Die ursprünglichen SLA-Ziele gelten weiter.',
            'first_heading' => 'Definition der ersten Reaktion',
            'first_intro' => 'Was zählt als „erste Reaktion“ — welcher Moment stoppt die Reaktionsuhr?',
            'first_either' => '<strong>Beides (Standard)</strong> &mdash; die erste Handlung eines Analysten gleich welcher Art: eine ausgehende E-Mail, eine Statusänderung, eine Zuweisung.',
            'first_status' => '<strong>Statusänderung</strong> &mdash; es zählt nur eine Statusänderung weg vom Standardstatus. Strenger — der Analyst muss tatsächlich am Ticket gearbeitet und nicht nur daraufgeklickt haben.',
            'first_email' => '<strong>Ausgehende E-Mail</strong> &mdash; es zählt nur eine E-Mail-Antwort an den Anfragenden. Am strengsten — der Kunde muss von uns gehört haben.',
            'warn_heading' => 'Warnschwelle in Prozent',
            'warn_body' => 'Wie weit das SLA-Ziel ausgeschöpft sein muss, bevor die Anzeige von Grün auf Gelb wechselt. Standard sind 80 % — ein Reaktionsziel von 60 Minuten wird also nach 48 Minuten gelb. Dieser Wert steuert auch die Verletzungsmeldungen vom Typ „Warnung“.',
        ],
        'breach' => [
            'heading' => 'Verletzungsmeldungen',
            'sub' => 'Je Abteilung konfigurierbare E-Mail-Regeln, die auslösen, wenn eine SLA sich einer Verletzung nähert (Warnung) oder tatsächlich verletzt wird.',
            'intro' => 'Jede Regel hat vier voneinander unabhängige Dimensionen:',
            'scope_heading' => '1. Geltungsbereich',
            'scope_body' => 'Entweder <strong>Standard</strong> (die Regel gilt für Tickets jeder Abteilung) oder eine <strong>bestimmte Abteilung</strong>. Auflösung: Eine abteilungsspezifische Regel sticht für Tickets dieser Abteilung die Standardregel. Ohne Standardregel erhalten Abteilungen ohne eigene Regel überhaupt keine Meldungen.',
            'trigger_heading' => '2. Auslöser',
            'trigger_body' => 'Entweder <strong>Warnung</strong> (das Ticket hat die Warnschwelle überschritten — mögliche Verletzung) oder <strong>Verletzung</strong> (das Ticket hat sein Ziel überschritten — tatsächliche Verletzung). Beides sind eigene Regeln, Sie können also für jeden Fall andere Personen benachrichtigen.',
            'target_heading' => '3. Ziel',
            'target_body' => 'Welche Uhr überwacht wird — <strong>Reaktion</strong>, <strong>Lösung</strong> oder <strong>beide</strong>.',
            'recip_heading' => '4. Empfänger',
            'recip_intro' => 'Beliebige Kombination aus:',
            'recip_assignee' => '<strong>Der zugewiesene Analyst des Tickets</strong> &mdash; wer das Ticket derzeit betreut. Entfällt, wenn es nicht zugewiesen ist.',
            'recip_teams' => '<strong>Mitglieder der Teams der Ticketabteilung</strong> &mdash; jeder Analyst in einem Team, das mit der Abteilung des Tickets verknüpft ist. Deckt die gesamte Warteschlange ab, ohne dass eine Verteilerliste gepflegt werden muss.',
            'recip_specific' => '<strong>Ein bestimmter Analyst</strong> &mdash; das Muster „SLA-Verantwortlicher“ bzw. „Service Manager“, bei dem es eine namentlich benannte Person ist und keine Rolle.',
            'recip_custom' => '<strong>Eigene E-Mail-Adressen</strong> &mdash; frei eingegeben, durch Kommas getrennt. Nützlich für gemeinsame Postfächer (<code>sla-alerts@firma.de</code>), E-Mail-Brücken zu Slack oder Teams sowie Verteilerlisten.',
            'tip' => 'Je Ticket wird höchstens eine E-Mail pro Kombination aus Ziel und Auslöser versendet — der Cron-Dienst merkt sich das Versendete in der Tabelle <code>sla_notifications_sent</code>. Eine Warnung löst also einmal aus, eine Verletzung einmal, und damit hat es sich — keine Endlosschleifen.',
            'warn' => '<strong>Keine Regeln = keine E-Mails.</strong> Selbst wenn jedes Ticket im System eine Verletzung aufweist, passiert nichts, bevor Sie mindestens eine Regel anlegen. Beginnen Sie mit einem Paar aus Warnung und Verletzung im Geltungsbereich „Standard“, um alles abzudecken.',
        ],
        'cron' => [
            'heading' => 'Den Cron-Job einrichten',
            'sub' => 'Das Skript zur Verletzungsprüfung muss planmäßig laufen. Alle 5 Minuten ist der beste Kompromiss.',
            'p1' => 'Die in der Oberfläche sichtbaren SLA-Anzeigen (Kennzeichen im Posteingang, Bereiche im Lesebereich) werden beim Laden der Seite berechnet. Verletzungs-E-Mails können aber nur ausgelöst werden, wenn <em>etwas</em> die Tickets von sich aus prüft, auch wenn niemand hinsieht. Dieses Etwas ist eine geplante Aufgabe — unter Windows die Aufgabenplanung, unter Linux cron.',
            'p2' => 'Das Skript ist <code>cron/sla_breach_check.php</code> im Installationsverzeichnis von FreeITSM. Es lässt sich auf zwei Wegen aufrufen:',
            'cli_heading' => 'A. CLI (empfohlen auf einem Server, den Sie selbst betreiben)',
            'cli_note' => 'Keine Authentifizierung nötig — die Dateisystemrechte regeln bereits, wer es ausführen darf.',
            'http_heading' => 'B. HTTP (für Shared Hosting oder externe Planer)',
            'http_note' => 'Das Token wird bei der ersten Installation automatisch erzeugt und in <code>system_settings</code> unter dem Schlüssel <code>sla_cron_token</code> gespeichert (32 Hexadezimalzeichen, rund 128 Bit Entropie). So finden Sie Ihres:',
            'win_heading' => 'Windows-Aufgabenplanung',
            'win_intro' => 'Öffnen Sie die Aufgabenplanung (<code>taskschd.msc</code>) und legen Sie eine neue Aufgabe mit diesen Einstellungen an:',
            'tbl_field' => 'Feld',
            'tbl_value' => 'Wert',
            'win_r1_k' => 'Name',
            'win_r1_v' => 'FreeITSM &mdash; SLA-Verletzungsprüfung',
            'win_r2_k' => 'Unabhängig von der Benutzeranmeldung ausführen',
            'win_r2_v' => 'Ankreuzen',
            'win_r3_k' => 'Trigger',
            'win_r3_v' => 'Täglich, alle 1 Tage wiederholen, alle 5 Minuten für die Dauer von 1 Tag',
            'win_r4_k' => 'Aktion',
            'win_r4_v' => 'Programm starten',
            'win_r5_k' => 'Programm/Skript',
            'win_r5_v' => '<code>C:\\wamp64\\bin\\php\\php8.2.x\\php.exe</code>',
            'win_r6_k' => 'Argumente hinzufügen',
            'win_r6_v' => '<code>C:\\wamp64\\www\\freeitsm-app\\cron\\sla_breach_check.php</code>',
            'win_r7_k' => 'Starten in',
            'win_r7_v' => '<code>C:\\wamp64\\www\\freeitsm-app</code>',
            'linux_heading' => 'Linux-cron',
            'linux_intro' => 'Fügen Sie Ihrer Crontab eine Zeile hinzu (<code>crontab -e</code>):',
            'sec_heading' => 'Sicherheit &mdash; was den HTTP-Endpunkt schützt',
            'sec_intro' => 'Drei Ebenen, alle automatisch wirksam:',
            'sec_token' => '<strong>1. Gemeinsames Geheimnis (Token)</strong> &mdash; 128 Bit Zufall je Installation, verglichen in konstanter Zeit, um Timing-Angriffe zu verhindern.',
            'sec_lockout' => '<strong>2. Sperre nach fehlgeschlagenen Versuchen je IP</strong> &mdash; mehr als 10 falsche Token von derselben IP innerhalb einer Stunde führen zu einer einstündigen Sperre mit HTTP 429. Wehrt Brute-Force-Versuche ab, ohne dass fail2ban nötig wäre.',
            'sec_interval' => '<strong>3. Mindestabstand zwischen erfolgreichen Läufen</strong> &mdash; <code>sla_cron_min_interval_seconds</code> (Standard 30 s). Selbst eine Anfrage mit gültigem Token erhält ein 429, wenn sie früher als das nach dem letzten erfolgreichen Lauf eintrifft. Wehrt versehentliche Doppelplanung und außer Kontrolle geratene Schleifen ab.',
            'log_heading' => 'Aktivitätsprotokoll',
            'log_body' => 'Jeder Aufruf (angenommen oder abgewiesen) wird mit Zeitangaben, Ergebnis, Anzahlen und Client-IP in der Tabelle <code>sla_cron_runs</code> protokolliert. Die letzten 20 Läufe sehen Sie im Bereich <strong>Cron-Aktivität</strong> unten im SLA-Reiter — nützlich, um zu prüfen, ob der Zeitplan greift, und um fehlgeschlagene Anmeldeversuche nachzuvollziehen. Zeilen werden nach <code>sla_cron_log_retention_days</code> (Standard 30) automatisch entfernt, damit die Tabelle klein bleibt.',
        ],
        'examples' => [
            'heading' => 'Durchgerechnete Beispiele',
            'sub' => 'Vom einfachen Fall in einer Zeitzone bis zum kniffligeren zeitzonenübergreifenden, bei dem erst zu klären ist, was „fair“ heißt.',
            'ex1_heading' => 'Beispiel 1: Ticket aus Deutschland, Service Desk in Deutschland',
            'ex1_title' => 'Der einfache Fall',
            'ex1_tag' => 'eine Zeitzone',
            'ex1_setup' => '<strong>Aufbau:</strong> Ein Geschäftskalender namens <em>Büro DE</em> mit der Zeitzone <code>Europe/Berlin</code>, Mo–Fr 09:00–17:00 Uhr, keine Feiertage. Die Priorität P2 hat ein Reaktionsziel von 1 Stunde und ein Lösungsziel von 4 Stunden, beide gegen den Kalender <em>Büro DE</em>.',
            'ex1_scenario' => '<strong>Szenario:</strong> Ein Benutzer erstellt am <strong>Mittwoch um 16:30 Uhr</strong> ein P2-Ticket.',
            'ex1_timeline' => 'Mi 16:30 &mdash; <strong>Ticket erstellt</strong>, die Reaktionsuhr startet.
Mi 17:00 &mdash; Büro schließt, die Uhr hält an (30 von 60 Minuten des Ziels verbraucht).
Do 09:00 &mdash; Büro öffnet, die Uhr läuft weiter.
Do 09:30 &mdash; ein Analyst antwortet. Reaktions-SLA punktgenau eingehalten (60 Minuten verbraucht, 60 Minuten Ziel).',
            'ex1_outro' => 'Hätte der Analyst erst am <strong>Donnerstag um 10:00 Uhr</strong> geantwortet, wäre die Reaktion <strong>um 30 Minuten verletzt</strong> worden (90 verbrauchte Minuten gegen ein Ziel von 60 — 30 vom Mittwochabend, 60 vom Donnerstagmorgen). Die Ein-Stunden-Uhr läuft nur während der Geschäftszeiten, aber ein Ticket vom Feierabend frisst über Nacht dennoch den größten Teil seines Budgets, sobald das Büro wieder öffnet — ein Analyst, der um 09:00 Uhr kommt, nimmt leicht an, er habe die volle Stunde, obwohl nur noch 30 Minuten übrig sind.',
            'ex2_heading' => 'Beispiel 2: Ticket aus Deutschland, Service Desk in Estland',
            'ex2_title' => 'Der zeitzonenübergreifende Fall',
            'ex2_tag' => '3 Arten, „fair“ zu definieren',
            'ex2_setup' => '<strong>Aufbau:</strong> Kunden in Deutschland (<code>Europe/Berlin</code>, MEZ/MESZ), Service Desk in Estland (<code>Europe/Tallinn</code>, EET/EEST &mdash; <strong>1 Stunde voraus</strong>). Beide arbeiten nominell von 09:00 bis 17:00 Uhr Ortszeit.',
            'ex2_scenario' => '<strong>Szenario:</strong> Ein deutscher Kunde erstellt am <strong>Freitag um 16:30 Uhr deutscher Zeit</strong> ein P2-Ticket (= 17:30 Uhr in Estland, nach Feierabend dort). Die nächste Gelegenheit für einen estnischen Analysten ist Montag 09:00 Uhr estnischer Zeit (= 08:00 Uhr deutscher Zeit). Das Reaktionsziel beträgt 1 Stunde.',
            'ex2_question' => 'Was sollte die SLA sagen? Es gibt drei vertretbare Antworten, jede in einem anderen Sinne fair. Welchen Kalender Sie der Priorität zuweisen, richtet sich danach, was Ihr Servicevertrag zusagt.',
            'optA_label' => 'Variante A &mdash; kundenzentriert',
            'optA_p1' => '<strong>Weisen Sie der Priorität einen Kalender mit <em>deutschen</em> Zeiten zu.</strong> Die Uhr läuft gegen 09:00–17:00 Uhr deutscher Zeit, unabhängig davon, wo der Analyst sitzt.',
            'optA_p2' => 'Im Szenario oben, Ticket am Freitag um 16:30 Uhr: Die Uhr läuft Freitag von 16:30 bis 17:00 Uhr (30 Minuten verbraucht), hält über Nacht und Wochenende an und läuft Montag um 09:00 Uhr weiter. Antwortet ein estnischer Analyst am Montag um 10:00 Uhr estnischer Zeit (= 09:00 Uhr deutscher Zeit), beginnt die Uhr gerade erst wieder — der Verbrauch bleibt bei 30 Minuten. <strong>SLA mit 30 Minuten Puffer eingehalten</strong>. Jede Antwort nach 09:30 Uhr deutscher Zeit (= 10:30 Uhr in Estland) wäre eine Verletzung.',
            'optA_p3' => '<em>Fair gegenüber:</em> dem Kunden. Sein Erleben entspricht seinem Arbeitstag.<br><em>Preis dafür:</em> Von estnischen Analysten wird erwartet, dass sie von 09:00 bis 17:00 Uhr deutscher Zeit erreichbar sind (= 10:00 bis 18:00 Uhr in Estland), was ihren Arbeitstag verlängert.',
            'optB_label' => 'Variante B &mdash; analystenzentriert',
            'optB_p1' => '<strong>Weisen Sie der Priorität einen Kalender mit <em>estnischen</em> Zeiten zu.</strong> Die Uhr läuft gegen 09:00–17:00 Uhr estnischer Zeit.',
            'optB_p2' => 'Gleiches Szenario: Ticket am Freitag um 17:30 Uhr estnischer Zeit (nach Feierabend), Uhr das ganze Wochenende angehalten, Start Montag um 09:00 Uhr estnischer Zeit (= 08:00 Uhr deutscher Zeit). Antwortet der Analyst am Montag um 09:30 Uhr estnischer Zeit (= 08:30 Uhr deutscher Zeit), sind 30 von 60 Minuten des Ziels verbraucht — <strong>mit 30 Minuten Puffer eingehalten</strong>. Der deutsche Kunde hat Freitag um 16:30 Uhr geschrieben und Montag um 08:30 Uhr eine Antwort erhalten — seine tatsächliche Wartezeit war weit länger, als die SLA vermuten lässt.',
            'optB_p3' => '<em>Fair gegenüber:</em> den Analysten. Sie arbeiten normale Zeiten.<br><em>Preis dafür:</em> Kunden in Deutschland kann die SLA „unehrlich“ vorkommen, wenn ein Ticket vom Freitagnachmittag erst am Montagmorgen estnischer Zeit bestätigt wird, der Bericht aber eine Reaktionszeit von 1 Stunde ausweist. Achten Sie darauf, dass Ihr Servicevertrag ausdrücklich sagt, dass die SLA gegen die Zeiten des Service Desks läuft.',
            'optC_label' => 'Variante C &mdash; Überschneidungsfenster (am strengsten)',
            'optC_p1' => '<strong>Weisen Sie der Priorität einen Kalender zu, der nur die Stunden abdeckt, in denen beide Standorte geöffnet sind.</strong> 09:00–17:00 Uhr deutscher Zeit überschneidet sich mit 09:00–17:00 Uhr estnischer Zeit (= 08:00–16:00 Uhr deutscher Zeit) im Fenster <strong>09:00–16:00 Uhr deutscher Zeit</strong> — 7 Stunden je Arbeitstag.',
            'optC_p2' => 'Gleiches Szenario: Ticket am Freitag um 16:30 Uhr deutscher Zeit (außerhalb der Überschneidung, die um 16:00 Uhr endet), Uhr über das Wochenende angehalten, läuft Montag um 09:00 Uhr deutscher Zeit weiter (= 10:00 Uhr in Estland, wenn die Überschneidung wieder beginnt). Antwortet der estnische Analyst um 10:30 Uhr estnischer Zeit (= 09:30 Uhr deutscher Zeit), sind 30 von 60 Minuten verbraucht — <strong>mit 30 Minuten Puffer eingehalten</strong>. Die Antwort fiel in das Überschneidungsfenster und zählt daher sofort.',
            'optC_p3' => '<em>Fair gegenüber:</em> beiden Seiten — die SLA läuft nur in Stunden, in denen der Desk das Ticket tatsächlich voranbringen kann UND der Kunde am Platz ist, um eine Antwort entgegenzunehmen.<br><em>Preis dafür:</em> Ein kürzeres Tagesfenster bedeutet längere tatsächliche Laufzeiten für ehrgeizige Ziele. Ein Lösungsziel von 4 Stunden erstreckt sich über etwa einen halben zusätzlichen Tag, während es mit einem normalen 8-Stunden-Kalender an einem Tag zu schaffen wäre.',
            'choose_tip' => '<strong>So wählen Sie:</strong> Sehen Sie in Ihren Servicevertrag. Steht dort „Reaktion innerhalb von 1 Stunde nach Eingang“ — das ist Variante A (Uhr des Kunden). Steht dort „Reaktion innerhalb von 1 Arbeitsstunde“ — das ist meist Variante B (der jeweils arbeitende Desk). Steht dort „innerhalb von 1 Stunde gemeinsamer Erreichbarkeit“ — das ist Variante C. Gibt es keinen Vertrag, fragen Sie das Team: Wollen Sie außerhalb estnischer Zeiten unter Druck stehen (Variante A), oder wollen Sie, dass deutsche Kunden sich gelegentlich übergangen fühlen (Variante B)?',
            'ex3_heading' => 'Beispiel 3: Die Uhr während einer Herstellerwartezeit anhalten',
            'ex3_title' => 'Wie Pausenstatus in der Praxis wirken',
            'ex3_tag' => 'Uhr anhalten',
            'ex3_setup' => '<strong>Aufbau:</strong> Priorität P3 mit einem Lösungsziel von 8 Geschäftsstunden, deutscher Kalender, Status „Wartet auf Hersteller“ mit dem Kennzeichen <em>SLA anhalten</em>.',
            'ex3_scenario' => '<strong>Szenario:</strong> Ticket am Montag um 09:00 Uhr erstellt. Der Analyst eskaliert am Montag um 11:00 Uhr zu Microsoft und setzt das Ticket auf „Wartet auf Hersteller“. Microsoft antwortet am Mittwoch um 14:00 Uhr. Der Analyst setzt die Lösung um und schließt am Donnerstag um 10:00 Uhr.',
            'ex3_timeline' => 'Mo 09:00 &mdash; Ticket erstellt, die Lösungsuhr läuft.
Mo 11:00 &mdash; auf „Wartet auf Hersteller“ gesetzt, <strong>Uhr angehalten</strong> (2 Std. verbraucht).
Mi 14:00 &mdash; zurück auf „In Bearbeitung“, <strong>Uhr läuft weiter</strong>.
Mi 17:00 &mdash; Büro schließt (insgesamt 5 Std. verbraucht).
Do 09:00 &mdash; Büro öffnet.
Do 10:00 &mdash; Ticket geschlossen (insgesamt 6 Std. verbraucht). <strong>SLA eingehalten</strong> gegen das 8-Stunden-Ziel.',
            'ex3_outro' => 'Tatsächlich verstrichen: rund 3 Tage. Auf die SLA angerechnet: 6 Arbeitsstunden. Ohne das Pausenkennzeichen hätte die SLA die 2 Tage Herstellerwartezeit samt Geschäftszeiten mitgezählt — insgesamt rund 18 Arbeitsstunden und damit deutlich über der Verletzungsgrenze.',
        ],
